(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["mt"] = {"ui":{"skip":"Aqbeż għall-kontenut","back":"← Lura għal AI-gile","lang.button":"Lingwa: {name}","lang.dialog":"Agħżel lingwa","lang.search":"Fittex lingwa","lang.none":"Ebda lingwa ma taqbel","lang.notYet":"Għad m'hemmx traduzzjoni għal {name}","theme.aria":"Aqleb it-tema: ċara, skura jew sewda","theme.toLight":"Aqleb għat-tema ċara","theme.toDark":"Aqleb għat-tema skura","theme.toBlack":"Aqleb għat-tema sewda (iswed veru, faċli fuq skrins OLED)","words.underline":"Issottolinja dawn il-kliem fil-paġna","words.underlineHelp":"Għaddi l-maws minn fuq kelma b'linja ta' tikek, jew agħfasha, biex tara xi tfisser.","words.col.todo":"Karti magħżula għalissa: it-tim se jibda minn dawn wara.","words.col.doing":"AI qed taħdem fuq din il-karta bħalissa.","words.col.review":"AI waħda lestiet ix-xogħol; oħra tivverifikah qabel ma jaslilek.","words.col.verify":"Qed jistenniek: ippruvah u għid jekk jaħdimx.","words.col.team":"In-noti jew it-tweġibiet tiegħek, qed jistennew li t-tim jerfagħhom.","words.col.done":"Lest u aċċettat.","index.title":"AI-gile: it-tim tal-iżvilupp tiegħek tal-AI, fuq bord wieħed","index.description":"AI-gile huwa bord kanban għal timijiet tal-kodiċi bl-AI. Jaħdmu waqt li torqod; inti tirċievi munzell wieħed qasir ta' affarijiet biex tiddeċiedi, tittestja u taċċetta.","hero.logoAlt":"Ikona tal-bord ta' AI-gile","hero.h1.html":"It-tim tal-iżvilupp tiegħek tal-AI, fuq bord&nbsp;wieħed.","hero.alpha":"🐣 Pre-alpha magħluqa","hero.alphaTitle":"Bikri u mhux lest: grazzi li qed tipprova!","hero.lede":"Jibnu waqt li torqod. Tqum għal munzell wieħed qasir: ftit mistoqsijiet, ftit affarijiet biex tittestja, djamant vjola jew tnejn. Ikklikkja, aċċetta, u lura għall-kafè tiegħek.","dl.windows":"Applikazzjoni għal Windows","dl.browser":"Mexxiha fil-browser tiegħek","dl.messenger":"📱 Messenger għat-telefon tiegħek","dl.soon":"Dalwaqt","dl.notify":"🔔 Għarrafni meta tiftaħ","dl.notifySmall":"Alpha jew beta","hero.secondary":"Agile, imma t-tim qatt ma jeħtieġ kafè għall-istand-up. (Jagħmlu l-istand-ups xorta waħda.)","pitch.h2":"AI-gile fi kliem kemm trid","pitch.lede":"Agħżel tul, minn kelma waħda sa 144. Kull tul huwa deskrizzjoni waħedha, miktuba għal dak id-daqs. Iġbed is-slider jew uża t-tasti tal-vleġeġ.","pitch.rangeLabel":"Tul f'kliem","pitch.dice":"🎲 verżjoni oħra","pitch.words.one":"{n} kelma","pitch.words.other":"{n} kelma","pitch.letters.one":"{n} ittra","pitch.letters.other":"{n} ittra","pitch.chars.one":"{n} karattru","pitch.chars.other":"{n} karattru","count.line.html.one":"{n} karta fuq il-bord bħalissa","count.line.html.other":"{n} karta fuq il-bord bħalissa","people.humans.html.one":"👥 {n} bniedem","people.humans.html.other":"👥 {n} bniedem","people.agents.html.one":"🤖 {n} aġent","people.agents.html.other":"🤖 {n} aġent","people.working.html.one":"⚡ {n} qed jaħdem bħalissa","people.working.html.other":"⚡ {n} qed jaħdmu bħalissa","pre.title":"AI-gile: qed tinbena xi ħaġa","pre.description":"Hawn qed tinbena xi ħaġa: bord fejn timijiet tal-AI jibnu dak li titlob, u jgħallmuk waqt li jaħdmu. Għalissa pre-alpha magħluqa mal-ħbieb.","pre.h1":"Hawn qed tinbena xi ħaġa. 🤫","pre.line":"Bord fejn timijiet tal-AI jibnu dak li titlob, u jgħallmuk waqt li jaħdmu. Għalissa pre-alpha magħluqa mal-ħbieb.","pre.btn":"🔔 Għarrafni meta tiftaħ","pre.peek":"Wara l-ħġieġ: il-bord veru, live. Kull karta hija strixxa kkulurita.","pre.peekFake":"Wara l-ħġieġ: hekk jidher bord fuq ix-xogħol.","pre.night":"🌙 Il-għassa tal-lejl qed imexxi · 😴 il-bniedem qed jistrieħ","features.aria":"X'jagħmel","f.pile.h":"Munzell wieħed għalik","f.pile.html":"<b>Għalik</b> iżomm kollox li qed jistenniek, fil-proġetti kollha: mistoqsijiet, affarijiet biex tittestja, kompiti li bniedem biss jista' jagħmel. Il-kju tiegħek jgħid x'inhu li jmiss u kemm se jieħu.","f.sleep.h":"Timijiet li jaħdmu waqt li torqod","f.sleep.p":"Kull proġett għandu lead u tim ta' aġenti tal-AI. Ikkumenta fuq karta u t-tim iqum, jagħmel ix-xogħol, u jirritornaha lura b'passi li bniedem għajjien jista' jsegwi.","f.tester.h":"Tester tal-AI jiċċekkja l-ewwel","f.tester.p":"Qabel ma xi ħaġa tasal għandek, tester isegwi l-passi f'kopja tal-app u juri x'ra, b'screenshot. Għaddi minn dawk li għaddew u aċċetta b'klikk wieħed.","f.proof.h":"Provi, mhux wegħdiet","f.proof.p":"Kull konsenja turi x'inbidel: il-fajls, id-diff, l-iscreenshots. M'għandekx bżonn tiftaħ kull app biex tara jekk huwiex lest.","f.chat.h":"Iddiskuti mal-leads tiegħek","f.chat.p":"Strixxa bi stil ta' Discord: ikona waħda għal kull proġett, djamanti vjola għal dak li jeħtieġek. Ibgħat idea lil lead; jagħmilha karti u pjan, b'buttuna ✅ Go.","f.tidy.h":"Iżomm lilu nnifsu f'ordni","f.tidy.p":"Karti relatati jingħaqdu f'waħda, titli mħawdin jissewwew, u kontroll tat-tokens iżomm il-kodiċi irqiq. Inqas affarijiet biex taqleb bejniethom, inqas biex taħseb fihom.","f.private.h":"Tiegħek, fuq il-kompjuter tiegħek","f.private.li1":"Il-bord jaħdem fuq il-magna tiegħek stess u jwieġeb lilek biss.","f.private.li2":"Il-messaġġi privati bejn in-nies huma ċifrati end-to-end.","f.private.li3":"L-ebda kont, l-ebda trackers, l-ebda cookies.","f.lang.h":"Bil-lingwa tiegħek","f.lang.p":"Aktar minn 120 lingwa, mill-Malti, il-Welsh u l-Ġappuniż sal-pirata, Yoda u l-Klingon, b'qlib mgħaġġel lura għall-Ingliż għat-termini tekniċi.","f.service.h":"Minn idea għal servizz veru","f.service.p":"Bnejt xi ħaġa bl-AI li issa n-nies qed jużawha? Immarkaha bħala servizz u l-bord jgħinek tmexxiha sew: uptime checks, paġna tal-istatus pubblika, inċidenti b'rapport, bidliet li jeħtieġu Go, backups iċċekkjati kuljum. L-Għajnuna tgħallmek kull pass hekk kif timxi.","msgr.h2":"AI-gile Messenger: it-tim tiegħek fil-but","msgr.p1":"Kellem lit-tim tal-AI tiegħek mingħajr ma tiftaħ il-bord. Iċċettja mal-mexxejja tal-proġetti u mal-ħbieb tiegħek, ara l-passi tat-test ta' karta u wieġeb għalihom, kollox mit-telefon tiegħek.","msgr.p2":"Biex tqabbdu, skennja kodiċi QR fuq il-bord tiegħek. L-ewwel darba? Chat demo ħbiberija turik kollox.","msgr.when":"L-ewwel Android, imbagħad verżjoni web għat-telefowns u għall-iPhone.","msgr.who":"Il-mexxej tal-proġett tiegħek","msgr.b1":"It-tiswija tal-modalità skura lesta. Trid il-passi tat-test?","msgr.b2":"Iva, jekk jogħġbok!","msgr.b3":"1. Iftaħ l-Issettjar. 2. Agħżel Skur. Jidher sew?","tl.aria":"Skeda taż-żmien mill-ewwel konversazzjoni sal-pjan","tl.h2":"Mill-ewwel chat sa dak li jmiss","tl.lede":"Dati u ħinijiet reali, fiż-żona tal-ħin tiegħek. Wara llum huwa l-pjan, mingħajr dati mwiegħda.","tl.today":"Illum","tl.planned":"ippjanat","tl.doing":"għaddej","tl.cards.one":"{n} karta","tl.cards.other":"{n} karta","join.h2":"Ingħaqad magħna","join.lede":"AI-gile qed jinbena minn wieħed stramb b'daqna, b'AuDHD u xi battalji mas-saħħa mentali, u numru kbir ta' aġenti paċenzjużi. Għalissa huwa privat, alpha magħluqa ma' ħbieb. Trid tipprova meta jinfetaħ?","join.btn":"Irreġistra l-interess","join.small":"Se nibagħtulek email, xejn aktar","footer.tag":"AI-gile. L-ebda trackers, l-ebda cookies, l-ebda kafè għall-istand-up.","footer.licence":"Liċenzja tan-negozju","footer.status":"Status","footer.privacy":"X'inżommu","footer.thanks":"Sejħiet grazzi għal ChilledChat","form.sending":"Qed jintbagħat…","form.failed":"Dak ma ħadimx: erġa' pprova aktar tard.","form.offline":"Ma setgħetx tintlaħaq AI-gile: erġa' pprova aktar tard.","form.keep":"Nużaw dan biss biex inwieġbuk, imbagħad inħassruh. L-ebda trackers, l-ebda cookies.","form.keepLink":"X'inżommu","interest.title":"AI-gile: għarrafni meta tiftaħ l-alpha","interest.description":"Ħalli l-email tiegħek biex tisma' meta tinfetaħ l-alpha jew il-beta magħluqa ta' AI-gile.","interest.h1":"🔔 Għarrafni meta tiftaħ","interest.lede":"AI-gile qiegħed f'pre-alpha magħluqa. Ħalli l-email tiegħek u niktbulek darba, meta jkun hemm post għalik.","interest.email":"L-email tiegħek","interest.which":"Liema test?","interest.alpha":"Alpha magħluqa: bikrija, mhux rfinuta, ħafna bidliet","interest.beta":"Beta: aktar stabbli, aktar tard","interest.both":"Kwalunkwe, dik li tiġi l-ewwel","interest.submit":"Poġġini fuq il-lista","interest.thanks":"Grazzi! Int fuq il-lista.","licence.title":"AI-gile: liċenzja tan-negozju","licence.description":"Qed tuża AI-gile fin-negozju tiegħek? Applika għal liċenzja tan-negozju b'xejn.","licence.h1":"📜 Liċenzja tan-negozju","licence.lede":"Qed tuża AI-gile x-xogħol? Għidilna min int u x'tagħmel. Jekk jagħmel xi ġid, il-liċenzja hija b'xejn.","licence.company":"Kumpanija","licence.website":"Websajt","licence.what":"X'tagħmel","licence.how":"Kif jgħin id-dinja","licence.email":"Email","licence.submit":"Applika","licence.thanks":"Grazzi! Nirrispondulek bl-email.","status.title":"Status ta' AI-gile","status.h1":"Status ta' AI-gile","status.quiet":"Kollox kwiet","status.intro":"AI-gile qed jaħdem bħalissa? Din il-paġna tiċċekkja s-sit, il-qsim tal-bordijiet, is-sejħiet u t-tniżżil kull 5 minuti.","status.up":"Qed jaħdem (wieġeb f'{ms} ms)","status.slow":"Ma weġibx għall-aħħar ċekk, qed nerġgħu nippruvaw","status.down":"Waqaf: ma weġibx għall-aħħar żewġ ċekkijiet","status.svc.web":"Sit web","status.svc.web.offers":"Dan is-sit: x'inhu AI-gile, u l-formola tal-interess","status.svc.boards":"Qsim tal-bordijiet","status.svc.boards.offers":"Bordijiet pubbliċi, messaġġi bejn il-ħbieb u stediniet","status.svc.calls":"Sejħiet","status.svc.calls.offers":"Vuċi, vidjo u qsim tal-iskrin f'AI-gile","status.svc.download":"Tniżżil","status.svc.download.offers":"L-installatur għal Windows u l-links tal-istediniet","status.checking":"Qed jiċċekkja…","status.offline":"Is-servizz tal-istatus ma jistax jintlaħaq bħalissa (qed nerġgħu nippruvaw)","status.updated":"aġġornat {ago}","status.justNow":"għadu kif","status.min":"{n} min ilu","status.hours":"{n} sieg ilu","status.days":"{n} j ilu","privacy.title":"AI-gile: x'inżommu","privacy.h1":"X'inżommu","privacy.lede":"Fil-qosor: biss dak li tibgħatilna, u mhux għal żmien twil.","privacy.only":"Biss dak li tibgħatilna: dak li tikteb f'formola, bħall-email tiegħek. Xejn iktar dwarek.","privacy.sealed":"Jiġi ssiġillat biex is-server tagħna ma jkunx jista' jaqrah: fil-browser tiegħek qabel ma jitlaq (fuq browser eqdem, hekk kif jasal). Il-bord tagħna biss jista' jiftħu.","privacy.server":"Jitħassar mis-server hekk kif jasal fuq il-bord tagħna. Kull ma jibqa' hemm wara 30 jum jitħassar xorta waħda.","privacy.board":"Inżommuh fuq il-bord tagħna biss sakemm inwieġbuk, imbagħad inħassruh minn hemm ukoll.","privacy.none":"L-ebda trackers, l-ebda cookies, l-ebda analitika.","privacy.local":"Il-lingwa tiegħek u l-għażla bejn tema ċara jew skura jibqgħu fil-browser tiegħek. Qatt ma jintbagħtulna.","privacy.ask":"Trid li jitħassar qabel? Wieġeb l-email tagħna u għidilna.","live.h2":"Ara kif qed jinbena, live","live.caption":"Kull karta hija moħbija: tara l-forma tax-xogħol, mhux il-kliem.","live.watching.one":"live: {n} qed josservaw","live.watching.other":"live: {n} qed josservaw","live.last.now":"L-aħħar karta tmexxiet ftit ilu","live.last.min.one":"L-aħħar karta tmexxiet {n} minuta ilu","live.last.min.other":"L-aħħar karta tmexxiet {n} minuti ilu","live.last.hour.one":"L-aħħar karta tmexxiet {n} siegħa ilu","live.last.hour.other":"L-aħħar karta tmexxiet {n} sigħat ilu","live.last.day.one":"L-aħħar karta tmexxiet {n} jum ilu","live.last.day.other":"L-aħħar karta tmexxiet {n} jiem ilu","live.offline":"Il-bord live qed jieħu nifs. Erġa' ejja dalwaqt.","live.cols":"Backlog|Biex isir|Għaddej|It-tim qed jivverifika|Għalik biex tittestja|Għat-tim|Lest","pitch.words.few":"{n} kelmiet","pitch.words.many":"{n} kelma","pitch.letters.few":"{n} ittri","pitch.letters.many":"{n} ittra","pitch.chars.few":"{n} karattri","pitch.chars.many":"{n} karattru","count.line.html.few":"{n} karti fuq il-bord bħalissa","count.line.html.many":"{n} karta fuq il-bord bħalissa","tl.cards.few":"{n} karti","tl.cards.many":"{n} karta","footer.models":"AI-gile iħaddem mudelli tal-IA għalik. Dak li jgħidu u jagħmlu huwa tagħhom, allura iċċekkjah qabel ma toqgħod fuqu.","privacy.ai.h":"Il-parti tal-IA","privacy.ai.models":"AI-gile huwa l-bord. Ix-xogħol jagħmluh mudelli tal-IA minn kumpaniji oħra, bħal Claude, Codex u Gemini, fuq il-kontijiet tiegħek stess.","privacy.ai.check":"Dak li jiktbu u jagħmlu jiġi minnhom u jista' jkun żbaljat. Iċċekkjah qabel ma toqgħod fuqu jew tippubblikah.","privacy.ai.files":"Jibdlu fajls u jmexxu kmandi fil-folders li tgħaqqad. Żomm backup.","privacy.ai.send":"Dak li tagħti lil mudell imur għand il-kumpanija li tmexxih, bil-kundizzjonijiet tagħha. Japplikaw il-kundizzjonijiet u l-ispejjeż ta' kull waħda.","privacy.ai.asis":"AI-gile hija verżjoni tat-test bikrija, mogħtija kif inhi."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Iddelegat."]},{"n":2,"texts":["Robots jaħdmu.","Aġenti, f'ordni.","Ideat, mibnija."]},{"n":3,"texts":["Kanban għar-robots.","Ideat isiru funzjonijiet.","B'xejn, lokali, ittestjat."]},{"n":5,"texts":["Bord kanban fejn jibnu l-aġenti.","Inti tikteb karti. Aġenti jibnu.","B'xejn, lokali, ittestjat, ftit iblah."]},{"n":8,"texts":["Bord kanban b'xejn fejn jaħdmu l-aġenti tal-AI.","Ikteb idea waħda. L-aġenti jibnuha. Inti taċċettaha.","Agile għal bniedem wieħed u ħafna robots paċenzjużi."]},{"n":13,"texts":["Bord kanban fuq il-kompjuter tiegħek fejn l-aġenti tal-AI jieħdu l-karti.","Ikteb idea. Tim sħiħ ta' aġenti jibnuha. Wara tester jiċċekkjaha sew għalik.","B'xejn, mingħajr kontijiet jew trackers: bord, ftit robots, u inti fil-kontroll."]},{"n":21,"texts":["AI-gile huwa bord kanban biex taħdem ma' aġenti tal-kodiċi bl-AI. Huma jieħdu l-karti kollha; inti tittestjahom u taċċettahom.","Kull proġett għandu lead u tim ta' aġenti tal-AI. Ikkumenta fuq kwalunkwe karta u t-tim jibda jaħdem.","Bord personali tal-affarijiet li jridu jsiru, b'xejn, li jaħdem fuq il-kompjuter tiegħek. Dawk li jaħdmu huma robots. Dak li jgħid iva int."]},{"n":34,"texts":["Inti tpoġġi l-ideat tiegħek fuq bord. Tim ta' aġenti tal-AI jibdilhom f'funzjonijiet li jaħdmu, jittestjahom, u jirritornawhom b'passi biex tipprova. Xejn ma jgħodd bħala lest sakemm int ma tgħidx hekk.","AI-gile huwa bord kanban magħmul id-dar li Rich bena b'ħafna għajnuna mill-aġenti li issa jmexxi. Huwa b'xejn, jaħdem fuq il-kompjuter tiegħek, u jinqasam ma' ħbieb, mhux jinbigħ.","Immaġina bord kanban tas-soltu, b'kolonni minn Backlog sa Lest, ħlief li l-karti jittieħdu mill-aġenti tal-AI. Jirrappurtaw il-progress, jistaqsu meta jibqgħu mwaħħla, u dejjem jistennew l-approvazzjoni tiegħek qabel ma jmorru 'l quddiem."]},{"n":55,"texts":["AI-gile huwa bord kanban fejn it-tim huwa magħmul minn aġenti tal-AI. Kull proġett għandu lead li jippjana x-xogħol u ħaddiema li jibnuh. Meta funzjoni tkun lesta, tester tal-AI jipprovaha u jieħu screenshot, imbagħad tasal fuq il-munzell tiegħek. Aċċettaha, jew ikkumenta u jerġgħu jaħdmu fuqha.","Beda bħala mod ta' persuna waħda biex iżomm rendikont ta' ħafna sessjonijiet tal-kodiċi bl-AI f'daqqa, u kiber f'bord veru. Jaħdem fuq il-magna tiegħek, ma jeħtieġ l-ebda kont u m'għandu l-ebda trackers. Huwa b'xejn għall-ħbieb u għal min hu kurjuż. Għadu wkoll mhux lest, għalhekk stenna xi truf mhux irfinati u sorpriża minn żmien għal żmien.","Din hija l-verżjoni onesta tal-istorja kollha. Xorta trid ikollok l-ideat, u xorta trid tiċċekkja r-riżultati. Dak li jagħmel AI-gile huwa dak kollu li hemm bejniethom: iżomm il-karti f'ordni, iqajjem l-aġent t-tajjeb meta tikkumenta, juri eżattament x'inbidel, u jżomm kollox f'munzell qasir wieħed biss għalik, mingħajr storbju."]},{"n":89,"texts":["AI-gile huwa bord kanban kompletament b'xejn li tmexxi fuq il-kompjuter tiegħek stess. Minflok in-nies, kull proġett għandu tim sħiħ ta' aġenti tal-AI: lead li jibdel l-ideat tiegħek f'karti u pjan, u għajnuna li tieħu l-karti skont il-prijorità. Meta xi ħaġa tinbena, tester tal-AI isegwi l-passi tat-test u juri lilek x'ra, b'screenshot. Imbagħad tistenna f'munzell wieħed biss jismu Għalik. Inti taċċettaha, jew tikkumenta u t-tim jerġa' jipprova mill-ġdid. Xejn ma jasal qatt f'Lest mingħajrek.","Ftit karatteristiċi li forsi ma tistennihomx. Għassa tal-lejl iżżomm il-kolonna Biex isir mimlija waqt li torqod, billi tagħżel karti li ma jeħtieġux tweġiba minnek. Għadd tat-tokens juri kemm użaw l-aġenti llum u din il-ġimgħa, u l-Mod bla Tokens jgħidilhom jieqfu jonfqu. Tista' tibgħat messaġġi lill-ħbieb, u l-messaġġi privati huma ċifrati end-to-end. Il-bord jitkellem madwar 120 lingwa, fosthom il-Malti, il-pirata u l-Klingon. Xejn minn dan ma jiswa xejn, u ħadd ma qed jipprova jbigħhulek.","AI-gile huwa proġett żgħir u personali, mhux kumpanija. Rich xtaq jieħu ħsieb diversi proġetti tal-kodiċi bl-AI mingħajr ma jiftaħ kull app biex jiċċekkjahom, allura hu u l-aġenti bnew bord għal dan, u mbagħad użaw il-bord biex jibnu l-bqija tiegħu nnifsu. Qiegħed f'pre-alpha magħluqa, li jfisser li jaħdem, il-biċċa l-kbira, għal ftit ħbieb. M'hemm l-ebda paġna tal-prezzijiet, l-ebda newsletter u l-ebda pjan ta' tkabbir. Jekk jidher utli, tista' titlob biex tipprovah meta jinfetaħ ftit aktar."]},{"n":144,"texts":["AI-gile huwa bord kanban għal bniedem wieħed u ħafna aġenti tal-AI paċenzjużi. Jaħdem fuq il-kompjuter tiegħek stess u huwa għal kollox b'xejn. Inti żżid proġetti, u kull proġett jaqla' lead u tim żgħir. Tiddiskuti mal-lead, kemmxejn bħal fuq Discord, u tiddeskrivi idea; il-lead jagħmilha karti u pjan, u jistenna li tagħfas Go. It-tim jaħdem mal-karti skont il-prijorità, b'għodda sempliċi tal-linja tal-kmandi magħmula għall-mudelli tal-lingwa. Qabel ma xi ħaġa tirritorna għandek, tester tal-AI isegwi l-passi f'kopja tal-app u jwaħħal screenshot. Ix-xogħol lest jasal fuq il-munzell tiegħek, mal-fajls li nbidlu, id-diff u l-iscreenshots. Inti taċċettah, jew tħalli kumment u t-tim iqum u jerġa' jipprova. Kull ma jsir jidher fuq il-bord, f'kolonni mill-Backlog sa Lest. Ma jeħtieġ l-ebda kont. Int biss tista' tmexxi karta għal Lest.","Jum ma' AI-gile, bejn wieħed u ieħor. Filgħaxija tħalli ftit kummenti: din il-buttuna hi fil-post ħażin, dik il-lista għandha tinżamm ordnata, nistgħu nkollhom mod skur. Tmur torqod. L-aġenti jaqraw il-kummenti, jagħmlu l-bidliet, jittestjawhom u jirritornawhom lilek. Jekk Biex isir jispiċċa, l-għassa tal-lejl timlieh mill-backlog b'karti li ma jeħtieġu l-ebda tweġiba minnek. Filgħodu hemm munzell qasir wieħed: par ta' mistoqsijiet u ftit affarijiet biex tipprova, kull wieħed b'passi li persuna ngħasana tista' ssegwi u screenshot ta' kif jaħdem. Tikklikkja minnu, taċċetta t-tajba u tibgħat lura l-bqija. Għadd tat-tokens juri kemm intuża dan kollu, u l-Mod bla Tokens hemm għal ġimgħat irqaq. Jekk xi ħaġa ma tkunx ċara, it-tim jistaqsi qabel ma jmur 'il quddiem. Imbagħad tieħu l-kolazzjon, li l-aġenti għadhom ma jistgħux jgħinu fih.","L-ewwel, x'mhuwiex AI-gile. Mhuwiex startup, mhuwiex għall-bejgħ, u ħadd ma qed jiġbor id-dejta tiegħek. Huwa bord b'xejn li jaħdem fuq il-kompjuter tiegħek, mingħajr kontijiet, trackers jew cookies. X'inhu: post wieħed irranġat biex tara l-proġetti kollha tiegħek tal-kodiċi bl-AI f'daqqa, b'tim ta' aġenti jagħmlu l-karti u inti tieħu d-deċiżjonijiet. Jingħaqad karti relatati, isewwi titli mħawdin, u josserva kemm il-kodiċi jibqa' irqiq. Jitkellem madwar 120 lingwa, mill-Malti sal-pirata u l-Klingon. Il-ħbieb jistgħu jibagħtu messaġġi lil xulxin, privatament u ċifrati. Inbena minn Rich u numru kbir ta' aġenti paċenzjużi, li l-aktar użawh huma stess. Ma jbigħ xejn, ma jitlob xejn, u ma jgħaddi xejn lil ħadd. Qiegħed f'pre-alpha magħluqa, għalhekk f'xi postijiet għadu mhux rfinut. Jekk jidher divertenti, itlob b'ġentilezza u forsi tidħol kmieni."]}],"quips":{"1":"Kelma waħda. Kuraġġuża. Forsi kuraġġuża żżejjed.","3":"Tliet kelmiet. Diġà aktar onesti mill-biċċa l-kbira tal-paġni tal-prodotti.","8":"Tmien kelmiet. Għadu iqsar minn stand-up.","21":"It-tulijiet huma story points, mill-mod. Naturalment.","55":"Ħamsa u ħamsin kelma. Żewġ karti ntemmu waqt li qrajt dan.","144":"Din kienet it-tawwala. M'hemm l-ebda 233. L-aġenti marru jorqdu."}},"timeline":{"first-idea.name":"L-ewwel idea","first-idea.line":"L-ewwel konversazzjoni ta' kollox, qabel ma kien jeżisti kodiċi.","first-board.name":"L-ewwel bord","first-board.line":"Bord li jżomm rendikont tal-bini tiegħu stess: karti, kolonni, ġbid u ċaqliq, proġetti.","team-roles.name":"Tim u rwoli","team-roles.line":"Profili tal-aġenti, mudelli tat-timijiet, spazji u min jagħmel xiex.","install.name":"Installazzjoni u rilaxxi","install.line":"Zip li ħabib jista' jinstalla, aġġornamenti awtomatiċi, kanali u rollback.","usage-saver.name":"Tfaddil tal-użu","usage-saver.line":"Kejl ta' kemm jiswew it-tħaddim, kodiċi irqiq, u l-limitu tiegħek jitfaddal.","friends.name":"Ħbieb u qsim","friends.line":"DMs privati, relay imħawwad, stediniet, rwoli u proġetti maqsuma.","languages.name":"Lingwi","languages.line":"Kull test tal-iskrin f'fajl tal-lingwa, bl-Olandiż u l-Fjamming l-ewwel.","ai-tester.name":"Tester tal-AI","ai-tester.line":"Tester jiċċekkja kull konsenja l-ewwel u juri x'ra.","website.name":"Is-sit","website.line":"aigile.lol, it-teaser u din l-iskeda taż-żmien.","streaming.name":"Chat u streaming","streaming.line":"Discord, Twitch, OBS, mod tal-istreamer, GIFs u emojis.","no-ai.name":"Edizzjoni bla AI","no-ai.line":"Bord għal nies li jikkodifikaw mingħajr AI, u bordijiet pubbliċi.","night-watch.name":"Għassa tal-lejl","night-watch.line":"Għassies u Scrum Master iżommu t-timijiet fuq il-binarju waqt li torqod.","p-more.name":"Kull ħaġa oħra","p-more.line":"Ideat iżgħar li għadhom jistennew id-dawra tagħhom.","p-android.name":"Telefon u Android","p-android.line":"Dħul fil-bord tiegħek mit-telefon, imbagħad app nattiva għall-Android.","p-release.name":"Alpha u aktar 'il quddiem","p-release.line":"Alpha magħluqa, is-sit live, imbagħad il-beta.","p-languages.name":"Aktar lingwi","p-languages.line":"130 lingwa, u mod ta' immersjoni għal min qed jitgħallem.","p-engines.name":"Aktar magni tal-AI","p-engines.line":"Agħżel Claude, Codex, Gemini, Copilot jew Cursor għal kull aġent.","p-pro.name":"Prattika professjonali","p-pro.line":"Tikketti tar-riskju, bibien tal-merge, karti tal-inċidenti u ħitan tal-ħarsien.","p-self.name":"Ngħożżuk","p-self.line":"Mod għajjien, tfakkiriet ta' kura personali u 4:20.","p-servers.name":"Servers u skala","p-servers.line":"Settings globali tas-server, rwoli u ppjanar għat-tkabbir.","p-livestream.name":"Żidiet għall-istreaming","p-livestream.line":"Chat ta' Twitch, emojis personalizzati u veduta live pubblika."},"words":{"button":"📖 Termini tekniċi","h":"📖 Kliem spjegat","intro":"Taħriġ b'xejn b'lingwa sempliċi: kull kelma li ssib mill-ewwel idea sa servizz li n-nies jistrieħu fuqu, bl-Agile, il-bini, li żżommu sigur u x-xogħol bl-AI matul it-triq.","search":"Fittex kelma…","none":"Ebda kelma ma taqbel ma' dak.","close":"Agħlaq","count":{"one":"{count} kelma","other":"Kliem: {count}"},"groups":[{"id":"idea","name":"💡 Idea u skoperta"},{"id":"plan","name":"🗺️ Ippjanar tax-xogħol"},{"id":"agile","name":"🔁 Modi ta' xogħol Agile"},{"id":"build","name":"🛠️ Il-bini"},{"id":"test","name":"🧪 Ittestjar u kwalità"},{"id":"change","name":"🔀 Bidla bla periklu"},{"id":"run","name":"🛎️ It-tmexxija ta' servizz"},{"id":"sec","name":"🔒 Sigurtà u privatezza"},{"id":"ai","name":"🤖 Xogħol bl-AI"},{"id":"money","name":"💰 Flus u liċenzji"}],"list":[{"id":"discovery","g":"idea","word":"Skoperta","text":"L-istadju bikri li fih issir taf liema problema jixraq li tissolva u għal min, qabel ma tinbena xi ħaġa.","also":["fażi tal-iskoperta","discovery"]},{"id":"problemstmt","g":"idea","word":"Dikjarazzjoni tal-problema","text":"Sentenza jew tnejn li jgħidu min għandu problema, x'inhi u għaliex hi importanti, biex kulħadd jimmira lejn l-istess ħaġa.","also":["dikjarazzjonijiet tal-problema","problem statement"]},{"id":"user","g":"idea","word":"Utent","text":"Persuna li tuża dak li tibni. Il-bżonnijiet tagħha huma l-għan tax-xogħol.","also":["utenti","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Kull min jimpurtah kif joħroġ ix-xogħol jew li jkun affettwat minnu, bħal dawk li jħallsu għalih, jużawh jew jappoġġawh.","also":["stakeholders","partijiet interessati"]},{"id":"persona","g":"idea","word":"Persona","text":"Persuna maħluqa iżda realistika li tirrappreżenta tip wieħed ta' utent, biex it-tim jistaqsi “Sam kien isib dan faċli?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"Riċerka dwar l-utenti","text":"Titkellem mal-persuni reali u tosservahom biex titgħallem x'għandhom bżonn, minflok tbassar.","also":["intervisti mal-utenti","user research"]},{"id":"journey","g":"idea","word":"Vjaġġ tal-utent","text":"Il-passi li persuna tieħu biex tlesti xi ħaġa, minn meta tisma' biha għall-ewwel darba sa meta tlestiha, anki barra mill-prodott tiegħek. Meta tpinġiha tara fejn tinqabad.","also":["vjaġġi tal-utent","vjaġġ tal-klijent","user journey","customer journey"]},{"id":"painpoint","g":"idea","word":"Punt ta' uġigħ","text":"Xi ħaġa li ddejjaq jew iddewwem lin-nies illum. Prodotti tajbin ineħħu l-punti ta' uġigħ.","also":["punti ta' uġigħ","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Assunzjoni","text":"Xi ħaġa li temmen iżda għadek ma kkontrollajtx. Jekk tikteb l-assunzjonijiet tara x'għandek tittestja l-ewwel.","also":["assunzjonijiet","assumption"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Ipoteżi","text":"L-aqwa tbassir li bi ħsiebek tivverifika, b'dak li tistenna li jiġri, bħal “in-nies jirreġistraw jekk l-ewwel xahar ikun b'xejn”.","also":["ipoteżijiet","hypothesis"]},{"id":"experiment","g":"idea","word":"Esperiment","text":"Test żgħir ippjanat biex titgħallem jekk idea taħdimx, qabel ma tpoġġi ħafna fiha.","also":["esperimenti","experiment"],"noTip":1},{"id":"poc","g":"idea","word":"Prova tal-kunċett (PoC)","text":"Prova mgħaġġla u mhux irfinuta biex tara jekk idea tistax taħdem tassew. Normalment titwarrab malli jkollok it-tweġiba.","also":["PoC","proof of concept","prova tal-kunċett"]},{"id":"prototype","g":"idea","word":"Prototip","text":"Mudell bikri tal-prodott, spiss stampi li tista' tikklikkja, biex tipprova l-idea fuq in-nies qabel ma tibniha sew.","also":["prototipi","prototype"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Abbozz sempliċi ta' skrin li juri fejn imur kull ħaġa, mingħajr kuluri jew kontenut reali.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Stampa dettaljata ta' kif se jidher skrin, b'kuluri u test reali, iżda għad xejn ma jaħdem.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Każ kummerċjali","text":"Ir-raġunijiet biex issir proġett: kemm jiswa, x'jdaħħal jew x'iffranka, u r-riskji.","also":["każijiet kummerċjali","business case"]},{"id":"feasibility","g":"idea","word":"Fattibbiltà","text":"Jekk xi ħaġa tistax tinbena u tinżamm tassew bil-ħin, bil-flus u bil-ħiliet li għandek.","also":["fattibbli","fattibbiltà","feasibility"]},{"id":"outcome","g":"idea","word":"Eżitu","text":"Il-bidla li trid għan-nies, bħal inqas appuntamenti mitlufa. Hi aktar importanti minn kemm tibni.","also":["eżiti","outcome"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Xi ħaġa li t-tim jagħmel, bħal skrin ġdid jew rapport. Li tagħmilha ma jfissirx awtomatikament li tgħin lil xi ħadd.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Metrika tas-suċċess","text":"Numru li jgħidlek jekk ix-xogħol għamilx dak li kien maħsub għalih, bħal aktar nies li jlestu l-ordni tagħhom.","also":["metriki tas-suċċess","success metric"]},{"id":"kpi","g":"idea","word":"Indikatur prinċipali tal-prestazzjoni (KPI)","text":"Numru importanti li żżomm għajnejk fuqu biex tara jekk l-affarijiet humiex sejrin tajjeb, bħal reġistrazzjonijiet fil-ġimgħa.","also":["KPI","KPIs","indikatur tal-prestazzjoni","key performance indicator"]},{"id":"okr","g":"idea","word":"Objettivi u riżultati ewlenin (OKRs)","text":"Mod kif tpoġġi miri: l-objettiv jgħid x'tixtieq, u ftit riżultati ewlenin huma n-numri li juru li wasalt.","also":["OKR","OKRs","objectives and key results"]},{"id":"product","g":"plan","word":"Prodott","text":"Dak li jinbena u jinżamm għall-utenti tiegħu, bħal app, websajt jew għodda.","also":["prodotti","product"],"noTip":1},{"id":"vision","g":"plan","word":"Viżjoni tal-prodott","text":"Dikjarazzjoni qasira dwar lil min jgħin il-prodott u lejn fejn sejjer fit-tul.","also":["dikjarazzjoni tal-viżjoni","vision statement"]},{"id":"po","g":"plan","word":"Sid il-prodott (PO)","text":"Il-persuna li tiddeċiedi x'jinbena u f'liema ordni, biex it-tim dejjem jaħdem fuq dak li hu l-aktar importanti. Fl-AI-gile dik int.","also":["PO","product owner","sidien tal-prodott"]},{"id":"pm","g":"plan","word":"Maniġer tal-prodott (PM)","text":"Il-persuna li tieħu ħsieb id-direzzjoni tal-prodott: liema problemi jsolvi, għal min u għaliex. PM jista' jfisser ukoll maniġer tal-proġett, għalhekk iċċekkja liema.","also":["PM","product manager","maniġers tal-prodott"]},{"id":"projmgr","g":"plan","word":"Maniġer tal-proġett","text":"Il-persuna li żżomm proġett fil-ħin u fil-baġit, issegwi min jagħmel xiex u sa meta.","also":["maniġers tal-proġett","project manager"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"Pjan mhux dettaljat ta' dak li ġej fix-xhur li jmiss, b'ordni. Juri d-direzzjoni, mhux id-dati eżatti, u jinbidel hekk kif titgħallem.","also":["roadmaps","mappa tat-triq"]},{"id":"milestone","g":"plan","word":"Milestone","text":"Punt f'proġett li jixraq jiġi mmarkat, bħal “l-ewwel verżjoni ħajja” jew “100 utent”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Prodott minimu vijabbli (MVP)","text":"L-iżgħar verżjoni ta' prodott li xorta hi utli għal nies reali, biex titgħallem minnhom kmieni.","also":["MVP","MVPs","prodott minimu vijabbli","minimum viable product"]},{"id":"requirement","g":"plan","word":"Rekwiżit","text":"Xi ħaġa li l-prodott lest irid jagħmel jew ikun.","also":["rekwiżiti","requirement"],"noTip":1},{"id":"scope","g":"plan","word":"Ambitu","text":"Dak li hu inkluż fix-xogħol u, daqstant importanti, dak li m'huwiex.","also":["fl-ambitu","barra mill-ambitu","in scope","out of scope","scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"Meta jiżdied dejjem aktar max-xogħol ftit ftit, mingħajr ma jiftiehem xi ħadd fuq il-ħin jew l-ispiża żejda, u allura qatt ma jispiċċa.","also":["feature creep","tkabbir bla kontroll tal-ambitu"]},{"id":"feature","g":"plan","word":"Karatteristika","text":"Ħaġa waħda li l-prodott jista' jagħmel għan-nies, bħal “erġa' ssetja l-password tiegħek”.","also":["karatteristiki","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Biċċa xogħol kbira, kbira wisq biex issir f'daqqa, għalhekk titqassam f'karti iżgħar.","also":["epics"]},{"id":"story","g":"plan","word":"Storja tal-utent","text":"Biċċa xogħol żgħira miktuba mil-lat tal-utent: “Bħala xerrej, irrid inżomm il-basket tiegħi, biex inkun nista' nlestih aktar tard.” Tibda diskussjoni dwar x'għandu jinbena.","also":["storji tal-utent","user story","user stories"]},{"id":"ac","g":"plan","word":"Kriterji ta' aċċettazzjoni (AC)","text":"It-testijiet li karta trid tgħaddi biex titqies lesta, miftehma qabel jibda x-xogħol, bħal “il-basket għadu hemm wara li noħroġ u nidħol mill-ġdid”.","also":["AC","kriterji ta' aċċettazzjoni","acceptance criteria"]},{"id":"task","g":"plan","word":"Kompitu","text":"Xogħol wieħed li jrid isir, spiss pass żgħir minn storja akbar.","also":["kompiti","task"],"noTip":1},{"id":"ticket","g":"plan","word":"Biljett","text":"Kelma oħra għal karta: biċċa xogħol waħda jew talba waħda, segwita mill-bidu sal-aħħar.","also":["biljetti","ticket"]},{"id":"priority","g":"plan","word":"Prijorità","text":"Kemm xi ħaġa hi importanti jew urġenti meta mqabbla mal-bqija, biex ix-xogħol l-aktar importanti jmur l-ewwel.","also":["prijoritajiet","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prijoritizzazzjoni","text":"Li tqiegħed ix-xogħol skont l-importanza. Mod komuni hu MoSCoW: Must have (jrid ikun hemm), Should have (jixraq ikun hemm), Could have (jista' jkun hemm), Won't have (mhux din id-darba).","also":["prijoritizza","prijoritizzazzjoni","MoSCoW"]},{"id":"estimate","g":"plan","word":"Stima","text":"L-aqwa tbassir ta' kemm hi kbira jew twila biċċa xogħol. Hu tbassir, mhux wegħda.","also":["stimi","estimate","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"Mod kif tbassar id-daqs tax-xogħol billi tqabbel il-karti ma' xulxin (“madwar id-doppju ta' dik”) minflok bis-sigħat. Mhumiex biex tqabbel it-timijiet.","also":["story point","punti tal-istorja"]},{"id":"tshirt","g":"plan","word":"Daqsijiet tat-T-shirt","text":"Li tbassar id-daqs tax-xogħol bħala S, M, L jew XL. Veloċi u biżżejjed għall-ippjanar bikri.","also":["T-shirt sizing","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Logħba għall-istima: kulħadd juri karta tad-daqs fl-istess ħin, imbagħad l-ogħla u l-inqas jispjegaw għaliex.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dipendenza","text":"Meta biċċa xogħol ma tistax tibda jew tispiċċa sakemm oħra tagħmel hekk.","also":["dipendenzi","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Kull ma jwaqqaf ix-xogħol milli jimxi 'l quddiem issa, bħal tweġiba nieqsa jew għodda mkissra.","also":["blockers","ostaklu","ostakli"]},{"id":"deadline","g":"plan","word":"Skadenza","text":"Id-data sa meta xi ħaġa trid tkun lesta.","also":["skadenzi","deadline"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Xi ħaġa konkreta li x-xogħol jipproduċi u jgħaddi, bħal paġna li taħdem jew rapport.","also":["deliverables","riżultat konkret"]},{"id":"forecast","g":"plan","word":"Tbassir","text":"Previżjoni ta' x'aktarx se jiġri, bħal meta se jitlesta x-xogħol, ibbażata fuq dak li taf s'issa.","also":["tbassir","forecast"],"noTip":1},{"id":"metric","g":"plan","word":"Metrika","text":"Kull ma tkejjel u ssegwi maż-żmien, bħall-viżti tal-paġna jew kemm tieħu ħin tiswija.","also":["metriki","metric","metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"Dak li n-nies jgħidulek dwar ix-xogħol tiegħek, tajjeb u ħażin. Li tilqgħu kmieni u spiss hu l-qalba tal-Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Il-lista tal-istennija ta' ideat u xogħol li għadhom ma ġewx ippjanati, bl-aktar importanti fuq nett. Xejn hemmhekk ma jinħadem sakemm ma jmurx għal Biex isir."},{"id":"sprint","g":"agile","word":"Sprint","text":"Perjodu qasir u fiss ta' xogħol (spiss ġimgħa jew tnejn, qatt aktar minn xahar) b'għan u sett miftiehem ta' karti li jridu jitlestew.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Check-in mgħaġġel ta' kuljum: x'għamel kull membru tat-tim, x'se jagħmel wara, u x'qed iwaqqfu. Fi Scrum jissejjaħ id-daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up","laqgħa ta' kuljum"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Mod ta' xogħol fejn il-karti jimxu mal-kolonni ta' bord (bħal Biex isir, Għaddej, Lest) u t-tim jillimita kemm ikun għaddej f'daqqa, biex ix-xogħol jibqa' jiċċaqlaq."},{"id":"wip","g":"agile","word":"WIP limit","text":"WIP hu fil-qosor għal work in progress (xogħol għaddej). Limitu WIP huwa l-ogħla għadd ta' karti li kolonna għandha żżomm f'daqqa, biex it-tim ilesti l-affarijiet qabel ma jibda aktar.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definizzjoni ta' Magħmul","text":"Il-checklist qasira tat-tim ta' xi jfisser “magħmul”, bħal ittestjat u spjegat, qabel ma kard tingħatalek. It-tewmija tagħha, id-Definizzjoni ta' Lest biex jibda, tgħid meta kard tkun ċara biżżejjed biex tibda.","also":["Definition of Ready","DoD","DoR","definizzjoni ta' lest","definizzjoni ta' lest biex jibda"]},{"id":"retro","g":"agile","word":"Retro","text":"Ħarsa regolari lura lejn kif jaħdem it-tim, biex jaqblu fuq ħaġa jew tnejn x'jagħmlu aħjar id-darba li jmiss. Fil-qosor għal retrospettiva. Fl-AI-gile, retro tissuġġerixxi bidla fil-mod ta' xogħol tat-tim, u inti tgħid Go jew Mhux issa.","also":["retros","retrospettiva","retrospettivi"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Kulħadd għal xogħol wieħed: ħafna nies iħallu xogħol ieħor biex flimkien jirranġaw ħaġa urġenti waħda sakemm tinħall. Fl-AI-gile kull tim jgħin fuq proġett wieħed, u proġetti oħra jistennew sadanittant.","also":["swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Fi Scrum, il-persuna li tgħin lit-tim jaħdem sew: tneħħi dak li jwaqqafhom, iżżomm il-laqgħat fit-triq u tħarreġ drawwiet tajbin, mingħajr ma tikkmanda lil ħadd. Fl-AI-gile, il-Lead Scrum Master jinduna bil-karti mwaħħla, iħeġġeġ lit-timijiet u jfakkrek x'qed jistenna, fuq kull proġett.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Mod ta' xogħol f'passi żgħar: tibni ftit, turi riżultati reali spiss, titgħallem minn dak li jgħidu n-nies u tibdel il-pjan hekk kif tmur, minflok tippjana kollox mill-bidu.","also":["żvilupp Agile","modi ta' xogħol Agile"]},{"id":"manifesto","g":"agile","word":"Manifest Agile","text":"Dikjarazzjoni qasira miktuba fl-2001 minn nies li jagħmlu s-software. Tqiegħed in-nies, ix-xogħol li jaħdem, ix-xogħol mill-qrib mal-klijenti u t-tweġiba għall-bidla qabel pjanijiet tqal u dokumentazzjoni żejda.","also":["Manifesto for Agile Software Development","Agile Manifesto"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Il-mod eqdem ta' xogħol: tippjana kollox, imbagħad tibni kollox, imbagħad tittestja kollox, stadju wara l-ieħor. Bidliet tard huma diffiċli u għaljin.","also":["mudell waterfall","waterfall model"]},{"id":"iteration","g":"agile","word":"Iterazzjoni","text":"Dawra waħda fejn tibni xi ħaġa, tiċċekkjaha u ttejjibha. Ix-xogħol Agile huwa katina ta' dawn, u sprint hu tip wieħed.","also":["iterazzjonijiet","iteration","iterations"]},{"id":"increment","g":"agile","word":"Inkrement","text":"Biċċa ġdida li taħdem miżjuda mal-prodott f'sprint jew dawra ta' xogħol, li tidħol ma' dak li kien diġà hemm.","also":["inkrementi","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Mod popolari ta' xogħol Agile: tim żgħir jaħdem f'sprints qosra lejn għan, b'rwoli stabbiliti u ftit laqgħat regolari biex jippjana, jiċċekkja u jtejjeb."},{"id":"scrumteam","g":"agile","word":"Tim Scrum","text":"Il-grupp żgħir li jagħmel ix-xogħol fi Scrum: sid il-prodott, Scrum Master u l-iżviluppaturi.","also":["timijiet Scrum","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Avvenimenti Scrum","text":"Il-laqgħat regolari fi Scrum: l-ippjanar tal-isprint, id-daily scrum, ir-rieżami tal-isprint u r-retro. Ħafna jsejħulhom ċerimonji.","also":["ċerimonji","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Ippjanar tal-isprint","text":"Il-laqgħa fil-bidu ta' sprint fejn it-tim jaqbel għaliex l-isprint huwa importanti, liema karti se jieħu u kif jibda.","also":["laqgħa tal-ippjanar","sprint planning"]},{"id":"sprintgoal","g":"agile","word":"Għan tal-isprint","text":"Sentenza waħda li tgħid għal xiex hu sprint. Kompiti żgħar jistgħu jinbidlu matul it-triq, sakemm l-għan jintlaħaq.","also":["għanijiet tal-isprint","sprint goal"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Il-karti magħżula għall-isprint attwali, bil-pjan tat-tim biex jagħmilhom.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"Il-lista sħiħa u f'ordni ta' kull ma jista' jinbena għall-prodott, l-aktar importanti fuq nett. Tibqa' tinbidel hekk kif titgħallem.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Għan tal-prodott","text":"Ir-riżultat akbar li lejh qed jaħdem il-prodott, li jgħin lit-tim jagħżel x'jagħmel wara.","also":["għanijiet tal-prodott","product goal"]},{"id":"refinement","g":"agile","word":"Irfinar tal-backlog","text":"Li tgħaddi regolarment mill-backlog biex tirranġa, taqsam, tqiegħed f'ordni u żżid dettalji mal-karti, biex ikunu lesti biex jittieħdu. Imsejjaħ ukoll backlog grooming.","also":["backlog grooming","refinement","irfinar"]},{"id":"sprintreview","g":"agile","word":"Rieżami tal-isprint","text":"Laqgħa fl-aħħar ta' sprint fejn it-tim juri dak li lesta u jisma' x'jaħsbu n-nies, biex jiddeċiedi x'jiġi wara.","also":["rieżami tal-isprint","sprint review"]},{"id":"demo","g":"agile","word":"Demo","text":"Li turi x-xogħol lest jaħdem, live, lil dawk li talbuh.","also":["demos","dimostrazzjoni"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"Ammont fiss ta' ħin għal xi ħaġa. Meta jintemm, tieqaf, anki jekk mhux kollox lest.","also":["timeboxes","timeboxed"]},{"id":"velocity","g":"agile","word":"Veloċità","text":"Kemm xogħol it-tim normalment ilesti f'sprint, użat biex jiġi ppjanat kemm jittieħed id-darba li jmiss. Mhux punteġġ ta' kemm in-nies jaħdmu iebes.","also":["veloċità tat-tim","velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Kapaċità","text":"Kemm xogħol jista' jieħu t-tim f'perjodu, wara l-btajjel u xogħlijiet oħra.","noTip":1},{"id":"burndown","g":"agile","word":"Chart tal-burndown","text":"Chart tax-xogħol li fadal fi sprint li jinżel jum wara jum. Jekk il-linja tibqa' ċatta, xi ħaġa hi mwaħħla.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Chart tal-burnup","text":"Chart tax-xogħol lest li jogħla maż-żmien, ħdejn it-total ippjanat, biex tara meta se tasal.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Bord Kanban","text":"Il-bord innifsu: kolonna għal kull stadju tax-xogħol, bil-karti jimxu minn naħa għall-oħra.","also":["bordijiet Kanban","Kanban board"]},{"id":"pullsys","g":"agile","word":"Sistema ta' ġbid","text":"Mod ta' xogħol fejn xogħol ġdid jibda biss meta xi ħadd ikollu spazju biex jieħdu, minflok ma jiġi mitfugħ fuq pjanċa diġà mimlija.","also":["ibbażata fuq il-ġbid","pull system","pull-based"]},{"id":"flow","g":"agile","word":"Fluss","text":"Kemm ix-xogħol jimxi bla xkiel mal-bord. Fluss tajjeb ifisser li l-karti jibqgħu jimxu minflok jinġabru.","also":["fluss tax-xogħol","flow"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"Kemm idum minn meta xi ħadd jitlob xi ħaġa sa meta titlesta.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"Kemm karta tieħu ħin minn meta x-xogħol jibda fuqha tassew sa meta titlesta.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"Kemm karti jitlestew fil-ġimgħa, jew f'kull perjodu stabbilit.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"L-istadju wieħed fejn ix-xogħol jinġabar u jnaqqas il-pass ta' kollox warajh, bħall-għonq dejjaq ta' flixkun.","also":["bottlenecks","għonq il-flixkun"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"Ringiela mal-bord li tiġbor flimkien karti ta' tip wieħed, bħal xogħol urġenti jew il-karti ta' tim wieħed.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Mod ta' xogħol li jneħħi l-ħela (kull ma ma jgħinx lill-klijent) u jżomm ix-xogħol jiċċaqlaq."},{"id":"waste","g":"agile","word":"Ħela","text":"Fil-Lean, kull ma jieħu sforz iżda ma jgħinx lill-klijent, bħall-istennija, ix-xogħol mill-ġdid jew il-bini ta' affarijiet li ħadd ma juża.","noTip":1},{"id":"kaizen","g":"agile","word":"Titjib kontinwu","text":"Li ssir ftit ftit aħjar il-ħin kollu permezz ta' bidliet żgħar regolari, u mbagħad tivverifika jekk għenux. Ir-retros huma mod wieħed. Imsejjaħ ukoll kaizen.","also":["kaizen","titjib kontinwu"]},{"id":"selforg","g":"agile","word":"Tim li jorganizza lilu nnifsu","text":"Tim li jiddeċiedi hu stess kif jagħmel ix-xogħol, minflok ma jingħata struzzjonijiet pass pass.","also":["jorganizza lilu nnifsu","tim li jmexxi lilu nnifsu","self-organising team"]},{"id":"crossfunc","g":"agile","word":"Tim transfunzjonali","text":"Tim li għandu l-ħiliet kollha li jeħtieġ biex ilesti x-xogħol waħdu, bħad-disinn, il-bini u l-ittestjar.","also":["transfunzjonali","cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"Biċċa riċerka qasira b'timebox biex twieġeb mistoqsija qabel ma tintrabat max-xogħol veru.","also":["spike","spikes"]},{"id":"rework","g":"agile","word":"Xogħol mill-ġdid","text":"Li terġa' tagħmel xogħol għax ma kienx tajjeb fl-ewwel darba.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"Agile skalat (SAFe)","text":"Modi kif tuża l-Agile f'ħafna timijiet f'organizzazzjoni kbira. SAFe (is-Scaled Agile Framework) hu eżempju magħruf.","also":["Agile skalat","scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Il-folder tal-kodiċi tal-proġett bl-istorja sħiħa tal-commits tiegħu. Jista' jgħix fuq il-kompjuter tiegħek, fuq GitHub, jew it-tnejn.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Linja separata ta' xogħol fil-kodiċi, biex isiru bidliet mingħajr ma tmiss il-verżjoni prinċipali.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Snapshot issejvjat tal-kodiċi, b'nota qasira ta' x'inbidel. Dejjem tista' terġa' lura għal wieħed.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Li tibgħat is-snapshots issejvjati tiegħek (commits) minn dan il-kompjuter lejn il-kopja maqsuma online, bħal GitHub, biex ikollhom backup u oħrajn ikunu jistgħu jġibuhom."},{"id":"merge","g":"build","word":"Merge","text":"Li tgħaqqad il-bidliet minn fergħa waħda ma' oħra, normalment lura fil-verżjoni ewlenija."},{"id":"pr","g":"build","word":"Pull request","text":"Li titlob li l-bidliet ta' fergħa jiġu kkontrollati u magħquda mal-verżjoni ewlenija. Xi siti jsejħulha merge request.","also":["PR","PRs","merge request","talba ta' għaqda"]},{"id":"refactor","g":"build","word":"Refactor","text":"Tirranġa l-kodiċi mingħajr ma tibdel dak li jagħmel: fajls iżgħar, ismijiet iktar ċari, inqas ripetizzjoni."},{"id":"bug","g":"build","word":"Bug","text":"Xi ħaġa li ma taħdimx kif suppost.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Peer review","text":"It-tieni par għajnejn: xi ħadd għajr l-awtur jiċċekkja x-xogħol qabel ma jasal għandek, biex jgħaddu inqas żbalji. Fl-AI-gile AI oħra tiċċekkja kull karta.","also":["code review"]},{"id":"code","g":"build","word":"Kodiċi","text":"L-istruzzjonijiet miktuba li jgħidu lil kompjuter x'jagħmel. Imsejjaħ ukoll kodiċi sors.","also":["kodiċi sors","source code","code"],"noTip":1},{"id":"proglang","g":"build","word":"Lingwa tal-ipprogrammar","text":"Lingwa biex tikteb il-kodiċi, bħal JavaScript, Python jew Java. Kull waħda tkun tajba għal xogħlijiet differenti.","also":["lingwi tal-ipprogrammar","programming language"]},{"id":"developer","g":"build","word":"Żviluppatur (dev)","text":"Min jikteb u jibdel il-kodiċi. Imsejjaħ ukoll programmatur jew inġinier tas-software.","also":["żviluppatur","żviluppaturi","developer","programmatur","programmaturi","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programmi li jaħdmu fuq kompjuters u telefons, għall-kuntrarju tal-magni nfushom (il-hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Fil-qosor għal applikazzjoni: programm li n-nies jużaw biex jagħmlu xi ħaġa, fuq telefon, kompjuter jew fil-browser.","also":["apps","applikazzjoni","applikazzjonijiet"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"App li taħdem fil-browser, għalhekk m'hemm xejn x'tinstalla.","also":["web apps","applikazzjoni tal-web"]},{"id":"frontend","g":"build","word":"Front end","text":"Il-parti ta' app li tara u tikklikkja fuqha: l-iskrins, il-buttuni u l-kliem, spiss fil-browser tiegħek.","also":["front-end","frontend","naħa ta' quddiem"]},{"id":"backend","g":"build","word":"Back end","text":"Il-parti ta' wara l-kwinti ta' app li żżomm id-data u tagħmel ix-xogħol meta tikklikkja xi ħaġa, bħal meta tiċċekkja l-password tiegħek.","also":["back-end","backend","naħa ta' wara"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Li taħdem kemm fuq il-front end kif ukoll fuq il-back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"Interface tal-utent (UI)","text":"Dak li persuna tara u tuża fuq l-iskrin: it-tqassim, il-buttuni, il-menus u t-test.","also":["UI","user interface","interface"]},{"id":"ux","g":"build","word":"Esperjenza tal-utent (UX)","text":"Kif tħossok meta tuża xi ħaġa: faċli, ċara u pjaċevoli, jew konfuża u bil-mod.","also":["UX","user experience","esperjenza tal-utent"]},{"id":"accessibility","g":"build","word":"Aċċessibilità (a11y)","text":"Li tagħmel l-affarijiet użabbli minn kulħadd, inklużi nies li ma jarawx sew, ma jistgħux jużaw il-maws jew jużaw screen reader.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Disinn responsiv","text":"Li tagħmel il-paġni jidħlu u jaħdmu tajjeb fuq kull daqs ta' skrin, minn telefon sa monitor kbir.","also":["responsive design","responsiv"]},{"id":"designsys","g":"build","word":"Sistema tad-disinn","text":"Kit maqsum ta' kuluri, fonts, buttuni u regoli, biex kull skrin jidher u jaġixxi bl-istess mod.","also":["design system","design systems","sistemi tad-disinn"]},{"id":"architecture","g":"build","word":"Arkitettura","text":"Il-forma ġenerali ta' sistema: liema huma l-partijiet ewlenin u kif jitkellmu ma' xulxin."},{"id":"database","g":"build","word":"Database (DB)","text":"Maħżen organizzat ta' informazzjoni, bħal spreadsheet qawwi ħafna li l-app tista' taqra u tibdel.","also":["database","databases","DB","bażi tad-data"]},{"id":"schema","g":"build","word":"Skema tad-database","text":"It-tqassim ta' database: liema tabelli ta' informazzjoni għandha u x'jidħol f'kull waħda.","also":["schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Fil-qosor għal structured query language: il-lingwa użata biex ħafna databases jintalbu informazzjoni jew biex din tinbidel.","also":["Structured Query Language","lingwa strutturata tal-mistoqsijiet"]},{"id":"data","g":"build","word":"Data","text":"Informazzjoni miżmuma minn kompjuter, bħal ismijiet, ordnijiet jew settings.","also":["dataset","datasets","dejta"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Kompjuter dejjem mixgħul li jwieġeb talbiet minn kompjuters oħra, bħal meta jibgħat paġna tal-web meta żżurha.","also":["servers","server"]},{"id":"client","g":"build","word":"Klijent","text":"Il-parti li titlob xi ħaġa, normalment il-browser jew l-app tiegħek, li titkellem ma' server. Fin-negozju l-kelma tfisser ukoll sempliċement xerrej.","also":["klijenti","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Fil-qosor għal application programming interface: menu stabbilit ta' talbiet li programm wieħed jista' jagħmel lil ieħor, bħal meta tistaqsi servizz tat-temp għat-tbassir tal-lum.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Element wieħed fuq il-menu ta' API: indirizz tal-web li programm jista' jċempel biex jieħu jew jibgħat xi ħaġa.","also":["endpoints","punt tat-tmiem"]},{"id":"integration","g":"build","word":"Integrazzjoni","text":"Li tgħaqqad żewġ sistemi biex jaħdmu flimkien, bħal meta n-negozju tiegħek jibgħat l-ordnijiet lis-software tal-kontijiet.","also":["integrazzjonijiet","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Messaġġ li sistema waħda tibgħat lil oħra waħedha eżatt malli tiġri xi ħaġa, bħal “il-ħlas wasal”.","also":["webhooks"]},{"id":"library","g":"build","word":"Librerija","text":"Kodiċi lest li kiteb xi ħadd ieħor u li tista' terġa' tuża minflok ma tikteb int.","also":["librerijiet","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Struttura lesta biex tibni app li tiddeċiedi ħafna dwar kif jitqassam il-kodiċi, bħal qafas ta' dar li timlieh int.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"Kaxxa ta' għodda, kodiċi u eżempji biex tibni software għal pjattaforma jew servizz wieħed.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Dipendenza tas-software","text":"Librerija jew għodda li l-kodiċi tiegħek jeħtieġ biex jaħdem. Li żżommhom aġġornati huwa importanti għas-sigurtà.","also":["dipendenzi tas-software","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Pakkett","text":"Ġabra ta' kodiċi lest li tista' tinstalla u tuża fi proġett.","also":["pakketti","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Maniġer tal-pakketti","text":"Għodda li tieħu u taġġorna l-pakketti li l-kodiċi tiegħek jiddependi minnhom. npm hi waħda komuni.","also":["maniġers tal-pakketti","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"L-aktar għodda użata biex tinżamm l-istorja tal-bidliet fil-kodiċi, bħala commits u branches."},{"id":"github","g":"build","word":"GitHub","text":"Websajt li żżomm repos tal-Git online, biex it-timijiet ikunu jistgħu jaqsmu l-kodiċi, jirrieżaminaw il-bidliet u jsegwu x-xogħol."},{"id":"vcs","g":"build","word":"Kontroll tal-verżjonijiet","text":"Li żżomm storja sħiħa ta' kull bidla fil-fajls, biex tkun tista' tara min biddel xiex u terġa' lura jekk ikun meħtieġ. Git jagħmel hekk.","also":["kontroll tas-sors","version control","source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Li tagħmel kopja sħiħa tiegħek ta' repo, bl-istorja tiegħu, fuq il-kompjuter tiegħek.","also":["cloned","cloning","ikklonja"]},{"id":"pull","g":"build","word":"Pull","text":"Li tġib l-aħħar commits mill-kopja maqsuma (bħal GitHub) fuq il-kompjuter tiegħek. L-oppost ta' push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"Il-verżjoni uffiċjali tal-kodiċi li kulħadd jaħdem minnha, spiss imsejħa main jew master.","also":["master branch","fergħa ewlenija"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"Meta żewġ bidliet imissu l-istess linji b'modi differenti, għalhekk il-kompjuter ma jistax jgħaqqadhom u persuna jkollha tagħżel.","also":["merge conflicts","kunflitt tal-għaqda"]},{"id":"diff","g":"build","word":"Diff","text":"Veduta li turi eżatt x'inbidel bejn żewġ verżjonijiet: linji miżjuda u linji mneħħija.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Kopja tiegħek ta' repo ta' xi ħadd ieħor, li tista' tibdel mingħajr ma taffettwa dak tiegħu.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"Programm qasir li jagħmel xogħol wieħed waħdu, bħal li jirranġa l-fajls jew jniedi l-app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Li tibdel il-kodiċi f'xi ħaġa lesta biex taħdem, jew ir-riżultat innifsu, lest biex jaħdem.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Ikkompila","text":"Li tittraduċi kodiċi miktub mill-bnedmin f'forma li l-kompjuter jista' jħaddem direttament.","also":["ikkompilat","compile","compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"Tieqa tat-test fejn tikteb struzzjonijiet għall-kompjuter minflok tikklikkja. Imsejħa wkoll terminal.","also":["command line","command-line","CLI","terminal","linja tal-kmandi"]},{"id":"config","g":"build","word":"Konfigurazzjoni (config)","text":"L-issettjar li jikkontrolla kif jaġixxi s-software, miżmum separat mill-kodiċi biex ikun faċli li jinbidel.","also":["config","konfigurazzjoni","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"Issettjar mogħti lil programm meta jibda, spiss użat għal indirizzi jew passwords biex ma jinkitbux fil-kodiċi.","also":["environment variables","env var","varjabbli tal-ambjent"]},{"id":"debugging","g":"build","word":"Debugging","text":"Li tfittex għaliex xi ħaġa mhix taħdem, u tirranġaha.","also":["debug","debugged","tiswija tal-bugs"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Żewġ persuni (jew persuna u AI) jaħdmu fuq l-istess kodiċi flimkien, wieħed jikteb u l-ieħor jiċċekkja.","also":["pairing","ipprogrammar f'par"]},{"id":"docs","g":"build","word":"Dokumentazzjoni (docs)","text":"Spjegazzjonijiet miktuba ta' kif taħdem xi ħaġa jew kif tintuża.","also":["dokumentazzjoni","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"L-ewwel fajl li għandek taqra f'repo: x'inhu l-proġett u kif tħaddmu.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Sistema legacy","text":"Sistema eqdem li għadha qed tintuża u diffiċli biex tinbidel, spiss għax ftit nies għadhom jifhmuha.","also":["sistemi legacy","kodiċi legacy","legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Dejn tekniku","text":"Soluzzjonijiet malajr li jiffrankaw il-ħin issa iżda jdewmu l-bidliet aktar tard, bħal self li jiġbor l-imgħax. Ir-refactoring iħallsu lura.","also":["dejn tekniku","technical debt","tech debt"]},{"id":"test","g":"test","word":"Test","text":"Kontroll li xi ħaġa taħdem kif suppost. Xi testijiet iħaddimhom il-kompjuter waħdu kull darba li l-kodiċi jinbidel; oħrajn huma int tipprova karta lesta qabel taċċettaha.","also":["testijiet","tittestja","jiġu ttestjati"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Fil-qosor għal quality assurance (żgurar tal-kwalità): kull ma jsir biex jiġi żgurat li x-xogħol ikun sew qabel ma jmur live. Fl-AI-gile dan ifisser il-kontrolli awtomatiċi: meta l-QA tkun ħamra, xi ħaġa falliet, u ma tistax tmur live sakemm tiġi rranġata.","also":["kontrolli tal-kwalità"]},{"id":"testpile","g":"test","word":"Munzell tat-test","text":"Il-kards lesti li qed jistennewk tipprovahom, waħda wara l-oħra. Aċċetta waħda jew ibgħatha lura b'nota, u titla' dik li jmiss.","also":["munzelli tat-test"]},{"id":"autotest","g":"test","word":"Test awtomatiku","text":"Kontroll li l-kompjuter iħaddem waħdu kull darba li l-kodiċi jinbidel, biex jinqabdu l-iżbalji kmieni.","also":["testijiet awtomatiċi","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Test manwali","text":"Persuna tipprova x-xogħol bl-id biex tara jaġixxix kif suppost.","also":["testijiet manwali","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"Kontroll awtomatiku żgħir ta' biċċa kodiċi waħda żgħira waħedha.","also":["unit tests","test tal-unità"]},{"id":"integtest","g":"test","word":"Test tal-integrazzjoni","text":"Kontroll li bosta partijiet jaħdmu sew flimkien, mhux wieħed wieħed biss.","also":["testijiet tal-integrazzjoni","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Test end-to-end (E2E)","text":"Test li jaġixxi bħal utent reali mill-bidu sal-aħħar, bħal li tirreġistra, tixtri u thallas.","also":["E2E","end-to-end tests","test minn tarf sa tarf"]},{"id":"uat","g":"test","word":"Test tal-aċċettazzjoni tal-utent (UAT)","text":"In-nies li talbu x-xogħol jippruvawh huma stess u jgħidu jekk jagħmilx dak li jeħtieġu. Il-munzell tat-test ta' AI-gile hu l-verżjoni tiegħu ta' dan.","also":["UAT","acceptance testing","test tal-aċċettazzjoni"]},{"id":"regression","g":"test","word":"Regressjoni","text":"Xi ħaġa li kienet taħdem iżda tkissret wara bidla. It-testijiet tar-regressjoni jiċċekkjaw li l-affarijiet l-qodma għadhom jaħdmu.","also":["regressjonijiet","regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"Kontroll mgħaġġel ħafna biex tara jekk l-affarijiet ewlenin jaħdmux, per eżempju eżatt wara li bidla tmur live. Jekk jonqos, waqqaf u ħares.","also":["smoke tests","test tad-duħħan"]},{"id":"exploratory","g":"test","word":"Ittestjar esploratorju","text":"Li tipprova l-prodott liberament u tfettex fih b'modi differenti, biex issib problemi li l-kontrolli ppjanati ma jindunawx bihom.","also":["ittestjar esploratorju","exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"Xenarju wieħed miktub biex jiġi pprovat: il-passi, u x'suppost jiġri.","also":["test cases","każ tat-test"]},{"id":"coverage","g":"test","word":"Kopertura tat-test","text":"Kemm mill-kodiċi jiġi kkontrollat minn testijiet awtomatiċi. Aktar hu normalment aktar sigur, imma kopertura għolja waħedha ma tipprovax li jaħdem tajjeb.","also":["kopertura tat-test","test coverage","code coverage","kopertura tal-kodiċi"]},{"id":"testdata","g":"test","word":"Data tat-test","text":"Informazzjoni ta' eżempju maħluqa li tintuża waqt l-ittestjar, biex id-dettalji privati ta' persuni reali ma jiġux esposti.","also":["data tat-test","test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"Sitwazzjoni mhux tas-soltu fil-limiti, bħal formola vojta jew isem b'apostrofu, fejn l-affarijiet spiss jinkisru.","also":["edge cases","każ estrem","każijiet estremi"]},{"id":"happypath","g":"test","word":"Happy path","text":"It-triq normali fejn kollox imur sew. Ittestjar tajjeb jipprova wkoll it-toroq fejn l-affarijiet imorru ħażin."},{"id":"perftest","g":"test","word":"Ittestjar tal-prestazzjoni","text":"Li tiċċekkja kemm xi ħaġa hi mgħaġġla u kemm tlaħħaq tajjeb taħt pressjoni.","also":["ittestjar tal-prestazzjoni","performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Ittestjar tat-tagħbija","text":"Li tiċċekkja kif sistema tlaħħaq meta ħafna nies jużawha f'daqqa.","also":["ittestjar tat-tagħbija","load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Ittestjar tas-sigurtà","text":"Li tfittex dgħufijiet li jistgħu jħallu lil xi ħadd jabbuża minn sistema jew jara dak li m'għandux.","also":["ittestjar tas-sigurtà","security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Ittestjar tal-aċċessibilità","text":"Li tiċċekkja li nies b'kapaċitajiet differenti jistgħu jużaw il-prodott, anki b'screen reader jew bil-keyboard biss.","also":["ittestjar tal-aċċessibilità","accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"Kontroll awtomatiku li jinduna b'żbalji possibbli u stil mħawwad fil-kodiċi, bħal spell checker għall-programmi.","also":["linter","lint"]},{"id":"static","g":"test","word":"Analiżi statika","text":"Li tiċċekkja l-kodiċi għal problemi billi taqrah awtomatikament, mingħajr ma tħaddmu.","also":["analiżi statika","static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Test inkostanti","text":"Test li xi drabi jgħaddi u xi drabi jfalli mingħajr raġuni ċara, għalhekk ma tistax tafdah għal kollox.","also":["testijiet inkostanti","flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Irriproduċi (repro)","text":"Li tagħmel bug jerġa' jiġri apposta billi ssegwi l-istess passi, biex ikun jista' jiġi studjat u rranġat. Li tikteb dawk il-passi hi l-aktar parti utli ta' rapport ta' bug.","also":["repro","reproduce","steps to reproduce","passi biex tirriproduċi"]},{"id":"severity","g":"test","word":"Severità","text":"Kemm hu ħażin l-effett ta' problema, minn fastidju żgħir sa meta kollox jieqaf.","also":["livell ta' severità","severity","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Li tikkopja verżjoni ġdida tas-software fuq il-kompjuters li jħaddmuh, bħal kopja tat-test jew is-servizz live."},{"id":"release","g":"change","word":"Release","text":"Pakkett b'isem ta' xogħol lest li jmur live flimkien, b'noti qosra fuq x'inbidel. 🚀 Releases jikteb in-noti mill-kards lesti.","also":["releases","rilaxx"]},{"id":"rollback","g":"change","word":"Rollback","text":"Li terġa' lura għall-aħħar verżjoni li kienet taħdem meta waħda ġdida ġġib inkwiet. Fl-AI-gile, Roll back jiġbor il-passi tat-tneħħija miktuba fuq kull bidla f'checklist waħda.","also":["roll back","erġa' lura","mreġġa' lura"]},{"id":"live","g":"change","word":"Live","text":"Il-verżjoni vera li n-nies jużaw, mhux kopja biex tipprova l-affarijiet. L-iżviluppaturi jsejħulha wkoll production.","also":["production","produzzjoni"],"noTip":1},{"id":"change","g":"change","word":"Bidla","text":"Bidla ppjanata f'xi ħaġa li n-nies jiddependu fuqha, miktuba minn qabel: x'inhi, għaliex, ir-riskju, meta, u kif tiġi mreġġa' lura. Ibda waħda b'🔀 Ressaq bidla.","also":["bidliet","talba għal bidla","talbiet għal bidla"],"noTip":1},{"id":"risk","g":"change","word":"Riskju","text":"Xi ħaġa li tista' tmur ħażin, b'punteġġ skont kemm hi probabbli u kemm tkun ħażina. ⚠️ Riskji jżommhom f'lista waħda, l-ogħla punteġġ l-ewwel, kull wieħed b'data biex terġa' tħares lejh.","also":["riskji","reġistru tar-riskji"]},{"id":"chgwin","g":"change","word":"Tieqa tal-bidliet","text":"Il-ħinijiet meta l-bidliet jistgħu jmorru live, bħal filgħaxija kwieta ta' nhar ta' Tlieta. Barra minn tieqa, kard tal-bidla ma tistax titlesta, sakemm ma tkunx emerġenza.","also":["twieqi tal-bidliet","tieqa"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Kontroll finali eżatt qabel ma bidla tmur live: kull persuna li trid tapprova tgħid Go jew No go. Timxi 'l quddiem biss meta kulħadd jgħid Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approvazzjoni","text":"Tistenna \"iva\" qabel ma jibda x-xogħol. Kard li jressaq xi ħabib, jew bidla, tistenna f'✅ Approvazzjonijiet sakemm tapprovaha jew tirrifjutaha.","also":["approvazzjonijiet"]},{"id":"quiettime","g":"change","word":"Ħin kwiet","text":"Perjodu ta' ħin, bħal waqt live stream, demo jew matul il-lejl, meta xejn ma jmur live. It-timijiet ikomplu jaħdmu u jittestjaw, imma t-tqegħid live jistenna sakemm jintemm. Postijiet oħra jsejħulha change freeze.","also":["ħinijiet kwieti","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Mod ta' xogħol fejn dawk li jibnu s-software u dawk li jħaddmuh jaħdmu bħala tim wieħed, b'ħafna awtomazzjoni, biex il-bidliet imorru live spiss u b'mod sigur."},{"id":"cicd","g":"change","word":"CI/CD (integrazzjoni u kunsinna kontinwa)","text":"Il-bidliet ta' kulħadd jingħaqdu fil-verżjoni prinċipali spiss u jiġu kkontrollati awtomatikament kull darba (integrazzjoni kontinwa), biex is-software dejjem ikun lest li jmur live b'daqqa ta' buttuna (kunsinna kontinwa).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","integrazzjoni kontinwa","kunsinna kontinwa"]},{"id":"contdeploy","g":"change","word":"Skjerament kontinwu","text":"Pass 'il quddiem mill-kunsinna kontinwa: kull bidla li tgħaddi mill-kontrolli tmur live waħedha, bla buttuna x'tagħfas.","also":["skjerament kontinwu","continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Is-serje awtomatika ta' passi li bidla tgħaddi minnhom fi triqitha lejn live, bħal build, test, imbagħad deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Ambjent","text":"Kopja separata waħda tas-sistema għal skop wieħed, bħal waħda biex tibni fiha, waħda biex tittestja fiha u dik live.","also":["ambjenti","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Ambjent tal-iżvilupp","text":"Il-kopja li fiha jaħdem żviluppatur, spiss fuq il-kompjuter tiegħu stess, fejn jekk tinkiser xi ħaġa ma jweġġa' lil ħadd.","also":["ambjent tal-iżvilupp","development environment","dev environment"]},{"id":"testenv","g":"change","word":"Ambjent tat-test","text":"Kopja separata tas-sistema użata għall-ittestjar biss, biex is-servizz reali ma jintmessx.","also":["ambjenti tat-test","test environment","test environments"]},{"id":"staging","g":"change","word":"Staging","text":"L-aħħar kopja mwaqqfa eżatt bħal dik live, għal kontroll finali qabel ma bidla tmur live.","also":["staging environment","ambjent ta' staging"]},{"id":"artifact","g":"change","word":"Build artifact","text":"Il-fajl jew il-pakkett li build jipproduċi, lest biex jinħażen, jiġi kkontrollat jew jitpoġġa live.","also":["build artifacts","artifatt tal-build"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Tiswija urġenti mqiegħda live malajr, barra mill-pjan normali, għax xi ħaġa importanti nkisret.","also":["hotfixes","tiswija urġenti"]},{"id":"patch","g":"change","word":"Patch","text":"Aġġornament żgħir li jirranġa bug jew jagħlaq toqba fis-sigurtà. Li tapplika l-patches tas-sigurtà malajr huwa importanti.","also":["patches","security patch","security patches","patch tas-sigurtà"]},{"id":"version","g":"change","word":"Numru tal-verżjoni","text":"Tikketta bħal 2.4.1 li tgħid liema rilaxx għandek. Spiss l-ewwel numru jinbidel għal bidliet kbar u l-aħħar għal tiswijiet żgħar.","also":["numri tal-verżjoni","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Noti tar-rilaxx","text":"Lista qasira u ċara ta' x'inbidel f'rilaxx, għal dawk li jużawh, inklużi tiswijiet u limiti magħrufa. Imsejħa wkoll changelog.","also":["noti tar-rilaxx","release notes","changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"Swiċċ mixgħul u mitfi għal karatteristika, biex xogħol ġdid ikun jista' jmur live moħbi u jinxtegħel (jew jintefa mill-ġdid) mingħajr rilaxx ġdid.","also":["feature flags","feature toggle","feature toggles","bandiera tal-karatteristika"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Li tirranġa rilaxx ħażin billi toħroġ malajr verżjoni ġdida u korretta minflok tmur lura għall-qadima.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Rilaxx canary","text":"Li tpoġġi bidla live għal grupp żgħir l-ewwel, u għal kulħadd biss meta tidher tajba. Jieħu ismu mill-kanarini li l-minaturi kienu jieħdu taħt l-art bħala twissija bikrija.","also":["rilaxx canary","canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Skjerament blu-aħdar","text":"Li żżomm żewġ kopji tas-sistema live u twassal lin-nies għal dik il-ġdida f'daqqa, biex tkun tista' terġa' lura minnufih jekk imur ħażin.","also":["skjerament blu-aħdar","blue-green","blue-green deployment","blue green deployment"]},{"id":"zerodown","g":"change","word":"Skjerament mingħajr waqfien","text":"Li tpoġġi verżjoni ġdida live mingħajr ma s-servizz qatt jieqaf għall-utenti tiegħu.","also":["skjerament mingħajr waqfien","zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Immaniġġjar tal-bidla","text":"Li tgħin il-bidliet jirnexxu: titkejjel ir-riskju, tinkiseb l-approvazzjoni t-tajba u jintgħażel ħin tajjeb. Imsejjaħ ukoll change management.","also":["immaniġġjar tal-bidla","change enablement","change management"]},{"id":"cab","g":"change","word":"Bord konsultattiv tal-bidla (CAB)","text":"Grupp li jħares lejn bidliet importanti u jaqbel jekk u meta jistgħu jimxu 'l quddiem.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Bidla standard","text":"Bidla b'riskju baxx li ssir bl-istess mod ittestjat kull darba, għalhekk tkun approvata minn qabel.","also":["bidliet standard","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Bidla normali","text":"Bidla li teħtieġ li tiġi kkontrollata u approvata qabel ma tmur 'il quddiem.","also":["bidliet normali","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Bidla ta' emerġenza","text":"Bidla li trid issir immedjatament biex tirranġa jew tevita inkwiet serju, b'approvazzjoni aktar mgħaġġla biex taqbel.","also":["bidliet ta' emerġenza","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Awtomazzjoni","text":"Li tħalli lill-kompjuter jagħmel xogħol ripetut waħdu, biex ikun aktar mgħaġġel u jsir bl-istess mod kull darba.","also":["awtomazzjoni","automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruttura","text":"Il-magni, in-networks u s-servizzi li fuqhom jaħdem is-software.","also":["infrastruttura","infra","infrastructure"]},{"id":"iac","g":"change","word":"Infrastruttura bħala kodiċi (IaC)","text":"Li tiddeskrivi s-servers u l-issettjar tiegħek f'fajls miżmuma mal-kodiċi, biex ikunu jistgħu jinbnew mill-ġdid eżatt bl-istess mod kull darba.","also":["IaC","infrastructure as code","infrastruttura bħala kodiċi"]},{"id":"cloud","g":"change","word":"Cloud","text":"Li tikri kompjuters, ħażna u servizzi minn fornitur kbir mal-internet, minflok ma tkun sid il-magni int.","also":["il-cloud","the cloud","cloud computing","kompjuting fil-cloud"]},{"id":"provider","g":"change","word":"Fornitur tal-cloud","text":"Kumpanija li tikri l-kompjuting mal-internet, bħal Amazon Web Services (AWS), Microsoft Azure jew Google Cloud.","also":["fornituri tal-cloud","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Il-post fejn l-app jew is-websajt tiegħek tgħix u taħdem biex in-nies jaslu għaliha, normalment mikri minn kumpanija.","also":["ospitar"]},{"id":"domain","g":"change","word":"Isem tad-dominju","text":"L-indirizz tal-web li n-nies jiktbu, bħal example.com. Tikrih kull sena, għalhekk irid jiġġedded.","also":["ismijiet tad-dominju","domain name","domain names","domain","dominju"]},{"id":"dns","g":"change","word":"DNS","text":"Fil-qosor għal domain name system: ir-rubrika tal-indirizzi tal-internet, li tibdel isem bħal example.com fl-indirizz tal-kompjuter it-tajjeb.","also":["domain name system","sistema tal-ismijiet tad-dominji"]},{"id":"container","g":"change","word":"Container","text":"Pakkett issiġillat li jżomm app u kull ma jeħtieġ, biex taħdem bl-istess mod fuq kull kompjuter. Docker hi l-aktar għodda magħrufa.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Magna virtwali (VM)","text":"Kompjuter finta li jaħdem ġewwa wieħed reali, biex magna kbira waħda tkun tista' taġixxi bħal ħafna.","also":["VM","VMs","virtual machine","virtual machines","magni virtwali"]},{"id":"serverless","g":"change","word":"Serverless","text":"Li tħaddem kodiċi mingħajr ma tieħu ħsieb ebda server int: il-fornitur iħaddmu meta jkun meħtieġ u inti thallas għal dak li tuża."},{"id":"lb","g":"change","word":"Load balancer","text":"Xi ħaġa li taqsam il-viżitaturi fuq diversi servers, biex ebda wieħed ma jkun mgħobbi żżejjed.","also":["load balancers","bilanċjatur tat-tagħbija"]},{"id":"cache","g":"change","word":"Cache","text":"Maħżen utli tar-riżultati riċenti miżmum fil-qrib, biex l-istess ħaġa ma jkollhiex tinġieb jew tinħadem mill-ġdid. Jekk tbattlu, tista' tirranġa paġni li jidhru skaduti.","also":["caches","caching","cached","memorja moħbija"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"Sett ta' servers madwar id-dinja li jżommu kopji tal-paġni u l-istampi tiegħek qrib il-viżitaturi, biex jitgħabbew malajr.","also":["CDN","netwerk tal-kunsinna tal-kontenut"]},{"id":"migration","g":"change","word":"Migrazzjoni","text":"Li tmexxi d-data jew sistemi minn setup qadim għal wieħed ġdid, jew li tibdel b'attenzjoni t-tqassim ta' database.","also":["migrazzjonijiet","migration","migrations","database migration","migrazzjoni tad-database"]},{"id":"service","g":"run","word":"Servizz","text":"Xi ħaġa li bnejt u li n-nies jiddependu fuqha, bħal websajt jew app, li tiġi mħarsa biex tibqa' taħdem. Immarka “Dan il-proġett huwa servizz” u għid x'joffri, min jużah u min hu on-call.","also":["servizzi","is-servizz"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Kemm mill-ħin servizz ikun qed jaħdem, normalment bħala perċentwali. 99.9% xorta jippermetti madwar 43 minuta waqfa fix-xahar.","also":["uptime percentage","perċentwali tal-uptime"]},{"id":"uptime","g":"run","word":"Uptime check","text":"Kontroll awtomatiku, kull ftit minuti, li s-servizz tiegħek għadu jwieġeb. Jekk jonqos diversi drabi wara xulxin, AI-gile jiftaħ kard ta' inċident waħdu.","also":["kontrolli tal-uptime","uptime checks","uptime check"]},{"id":"statuspage","g":"run","word":"Paġna tal-istatus","text":"Paġna pubblika li turi jekk servizz hux jaħdem (aħdar, oranġjo jew aħmar) bl-aħħar aġġornament, biex in-nies li jużawh ikunu jistgħu jiċċekkjaw minflok jistaqsu.","also":["paġni tal-istatus","status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Fejn jidħlu l-mistoqsijiet u r-rapporti min-nies li jużaw is-servizz tiegħek. AI-gile jqassam kull wieħed bħala talba, inċident jew idea, u jgħidlek meta jidher qisu xi ħaġa li diġà ġiet irrappurtata.","also":["service desks","help desk","helpdesk","desk tas-servizz"]},{"id":"svcrequest","g":"run","word":"Talba għal servizz","text":"Xi ħadd jitlob xi ħaġa ordinarja, bħal kont ġdid jew ftit għajnuna, minflok jirrapporta li xi ħaġa nkisret. Tistenna d-dawra tagħha; l-inċident jgħaddi l-ewwel.","also":["talbiet għal servizz"]},{"id":"incident","g":"run","word":"Inċident","text":"Xi ħaġa li hi mkissra jew ma taħdimx sew għan-nies li qed jużawha issa, bħal websajt li waqfet jew bil-mod ħafna. Karta ta' inċident 🔥 taqbeż il-kju: li terġa' tħaddimha jmur l-ewwel.","also":["inċidenti","l-inċident"]},{"id":"major","g":"run","word":"Inċident maġġuri","text":"Inċident kbir: ħafna nies affettwati, jew flus jew data f'riskju. Buttuna waħda tpoġġi kull tim fuqu (swarm), tqajjem lil min hu on-call u titlob aġġornament tal-istatus kull 30 minuta.","also":["inċidenti maġġuri"]},{"id":"oncall","g":"run","word":"On-call","text":"Tkun dak li jwieġeb meta xi ħaġa tinkiser, anke bil-lejl. Kull servizz għandu membru tat-tim on-call li jitqajjem l-ewwel għall-inċidenti tiegħu.","also":["on call"]},{"id":"replyby","g":"run","word":"Ħin biex titwieġeb","text":"Kemm kard tista' tistenna għall-ewwel tweġiba, pereżempju siegħa għal inċident. Wara dak il-ħin tieħu arloġġ aħmar, biex xejn ma jintesa bil-kwiet. Jissejjaħ ukoll mira ta' rispons.","also":["ħinijiet biex titwieġeb","mira ta' rispons","miri ta' rispons"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Ħarsa qasira lura wara inċident: x'ġara, x'għen u x'għandu jinbidel, mingħajr ma tagħti tort lil ħadd. Inċident ma jistax jingħalaq mingħajrha.","also":["post-mortems","postmortem","reviżjoni wara l-inċident"]},{"id":"problem","g":"run","word":"Problema","text":"Il-kawża moħbija wara inċident wieħed jew aktar. Kard ta' 🧩 problema tiġbor flimkien inċidenti li jibqgħu jerġgħu jiġru, biex il-kawża tinstab u tissewwa għal dejjem.","also":["problemi","il-problema"],"noTip":1},{"id":"rootcause","g":"run","word":"Kawża ewlenija","text":"Ir-raġuni vera għaliex xi ħaġa nkisret, mhux biss dak li rajt imur ħażin. Sewwi l-kawża ewlenija u l-inċident ma jibqax jerġa' jiġri.","also":["kawżi ewlenin","root cause"]},{"id":"workaround","g":"run","word":"Workaround","text":"Mod kif iżżomm l-affarijiet jaħdmu sakemm it-tiswija vera tkun lesta, bħal tirristartja xi ħaġa meta teħel. Jinkiteb fuq il-kard tal-problema biex ħadd ma jkollu jerġa' jaħsibha.","also":["workarounds","soluzzjoni temporanja"]},{"id":"knownerror","g":"run","word":"Żball magħruf","text":"Problema li l-kawża tagħha hi mifhuma imma għadha ma ġietx irranġata, normalment b'soluzzjoni temporanja miktuba. Il-paġna 🧩 Żbalji magħrufa telenkahom, biex kulħadd juża s-soluzzjoni temporanja minflok ma jerġa' jfittex mill-ġdid.","also":["żbalji magħrufa"]},{"id":"runbook","g":"run","word":"Runbook","text":"Struzzjonijiet pass pass biex issewwi tip ta' problema magħrufa, biex issir bl-istess mod, malajr, kull darba. Wara inċident kbir it-tim jista' jipproponi wieħed biex tagħtih l-OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Oġġett tal-konfigurazzjoni","text":"Ħaġa waħda li s-servizz tiegħek jiddependi minnha, bħal server, dominju, ċertifikat, ċavetta jew fornitur. 🗂️ Oġġetti tal-konfigurazzjoni jelenkahom għal kull servizz, biex tara x'jaffettwa inċident u x'jeħtieġ tiġdid jew backup.","also":["oġġetti tal-konfigurazzjoni"]},{"id":"expiry","g":"run","word":"Data ta' skadenza","text":"Id-data meta xi ħaġa tieqaf taħdem sakemm ma tiġix imġedda, bħaċ-ċertifikat tas-sigurtà ta' websajt jew l-indirizz tal-web tagħha. AI-gile tosserva dawn id-dati u tagħmel karta waħda biex iġġedded kull waħda 30 jum qabel, biex xejn ma jieqaf b'sorpriża.","also":["dati ta' skadenza","skadenza","sorveljanza tal-iskadenzi"]},{"id":"backup","g":"run","word":"Backup","text":"Kopja salvata tad-data tiegħek minn qabel, biex terġa' għaliha jekk xi ħaġa tintilef jew issirilha l-ħsara. AI-gile jagħmel backup tal-bordijiet tiegħek kuljum.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Irkupru","text":"Iġġib lura d-data minn backup. Backup verament jgħodd biss meta tkun taf li jista' jiġi rkuprat, għalhekk ta' min tipprovah kultant.","also":["irkupra","irkuprat","restore"]},{"id":"svcreview","g":"run","word":"Reviżjoni tas-servizz","text":"Ħarsa lura lejn xahar wieħed ta' servizz: inċidenti miftuħa u rranġati, kemm malajr in-nies kisbu tweġiba, uptime u tokens użati. Ir-Reviżjoni xahrija turih għal kull servizz.","also":["reviżjonijiet tas-servizz","reviżjoni xahrija","reviżjonijiet xahrin"]},{"id":"accessreview","g":"run","word":"Reviżjoni tal-aċċess","text":"Li kull 90 jum tiċċekkja min għad jista' jidħol: rabtiet maqsuma, rwoli tal-ħbieb u passwords u ċwievet salvati. Inti żżomm jew tneħħi kull wieħed, biex aċċess qadim ma jibqax hemm.","also":["reviżjonijiet tal-aċċess"]},{"id":"improvements","g":"run","word":"Lista tat-titjib","text":"Dak kollu li t-tim iddeċieda li jtejjeb, f'post wieħed: suġġerimenti tar-retro, azzjonijiet tar-reviżjonijiet u soluzzjonijiet għal problemi, kull wieħed bl-istatus tiegħu. Issibha taħt 📈 Titjib.","also":["listi tat-titjib","titjib"]},{"id":"tokencap","g":"run","word":"Limitu ta' token","text":"Limitu kull xahar fuq it-tokens li l-aġenti ta' servizz jistgħu jużaw. Fi 80% tirċievi twissija; f'100% ix-xogħol fl-isfond tagħhom jistenna sax-xahar ta' wara jew sakemm togħla l-limitu.","also":["limiti ta' token"]},{"id":"svcmgmt","g":"run","word":"Immaniġġjar tas-servizz","text":"Dak kollu involut biex servizz jibqa' utli u jaħdem għal dawk li jiddependu minnu, jum wara jum.","also":["immaniġġjar tas-servizz","service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Gwida użata ħafna għal immaniġġjar tajjeb tas-servizzi, li tkopri affarijiet bħal inċidenti, problemi u bidliet. L-isem darba kien ifisser IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Immaniġġjar tas-servizzi tal-IT (ITSM)","text":"Li tħaddem it-teknoloġija bħala servizz għan-nies, b'modi ċari kif jiġu mmaniġġjati talbiet, inċidenti, bidliet u titjib.","also":["ITSM"]},{"id":"managed","g":"run","word":"Servizz immaniġġjat","text":"Servizz li xi ħadd ieħor iħaddem u jieħu ħsiebu għalik, taħt ftehim dwar kemm irid jaħdem tajjeb.","also":["servizzi immaniġġjati","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Sid is-servizz","text":"Il-persuna li twieġeb għal servizz kollu kemm hu: kemm jaħdem tajjeb, kemm jiswa u kif jitjieb.","also":["sidien is-servizz","service owner","service owners"]},{"id":"sla","g":"run","word":"Ftehim dwar il-livell tas-servizz (SLA)","text":"Wegħda miktuba lill-klijenti dwar kemm servizz se jaħdem tajjeb, bħal “jaħdem 99.9% tal-ħin” jew “jitwieġeb fi żmien siegħa”, spiss b'flus lura jekk tinkiser.","also":["SLA","SLAs","service level agreement","ftehim dwar il-livell tas-servizz"]},{"id":"slo","g":"run","word":"Objettiv tal-livell tas-servizz (SLO)","text":"Il-mira tat-tim stess dwar kemm servizz għandu jaħdem tajjeb f'perjodu, normalment stabbilita ftit aktar stretta mill-SLA biex tkun sigura.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Indikatur tal-livell tas-servizz (SLI)","text":"Il-kejl attwali li tiċċekkja mal-mira, bħall-perċentwali ta' viżti li tgħabbew sew.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Disponibbiltà","text":"Jekk in-nies jistgħux jużaw servizz meta jkollhom bżonnu, spiss imkejla bħala uptime.","also":["disponibbiltà","availability","high availability","disponibbiltà għolja"]},{"id":"downtime","g":"run","word":"Downtime","text":"Il-ħin meta servizz ma jkunx qed jaħdem jew ikun mitfi, ippjanat jew le.","also":["down time","ħin ta' waqfien"]},{"id":"errorbudget","g":"run","word":"Baġit tal-iżbalji","text":"Il-ftit falliment li l-mira tal-affidabbiltà tiegħek tippermetti. Sakemm jibqa' xi ftit tista' tieħu riskji bil-bidliet; malli jintuża kollu, inti tnaqqas il-pass.","also":["baġit tal-iżbalji","error budget","error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"Ħin meta servizz ikun waqaf jew imkisser serjament għall-utenti tiegħu.","also":["outages","waqfa tas-servizz"]},{"id":"degraded","g":"run","word":"Degradat","text":"Jaħdem, imma ħażin: bil-mod, jew b'xi partijiet li ma jaħdmux.","also":["degradat","degraded","degraded service","servizz degradat"]},{"id":"monitoring","g":"run","word":"Monitoraġġ","text":"Li tissorvelja servizz awtomatikament il-ħin kollu, biex il-problemi jinqabdu, idealment qabel ma jindunaw l-utenti.","also":["monitoraġġ","monitoring","immonitorjat"]},{"id":"observability","g":"run","word":"Osservabbiltà","text":"Kemm tista' tgħid x'qed jiġri ġewwa sistema minn barra, billi tuża l-logs, in-numri u t-traċċi tagħha.","also":["osservabbiltà","observability","o11y"]},{"id":"log","g":"run","word":"Log","text":"Djarju kontinwu li programm iżomm ta' dak li qed jagħmel, użat biex jinstab x'mar ħażin.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Traċċa","text":"Rekord ta' kif talba waħda tivvjaġġa mill-partijiet differenti ta' sistema, pass pass, li juri fejn dewmet.","also":["traċċi","trace","traces","tracing"]},{"id":"latency","g":"run","word":"Latenza","text":"Kemm xi ħaġa tieħu ħin biex twieġeb, bħall-istennija bejn il-klikk u meta tidher il-paġna.","also":["latenza","latency"]},{"id":"alert","g":"run","word":"Allert","text":"Messaġġ awtomatiku li xi ħaġa teħtieġ attenzjoni, bħal meta l-websajt ma twieġebx.","also":["allerti","alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Għeja mill-allerti","text":"Meta jkun hemm tant allerti li n-nies jibdew jinjorawhom, inklużi dawk importanti.","also":["għeja mill-allerti","alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"Skrin li juri n-numri u l-istatus l-aktar importanti b'ħarsa waħda.","also":["dashboards","bord tal-kontroll"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Li tċempel jew tqajjem urġentement lill-persuna on-call dwar problema.","also":["paged"]},{"id":"escalation","g":"run","word":"Eskalazzjoni","text":"Li ddaħħal lil xi ħadd b'aktar ħila jew awtorità meta kwistjoni ma tistax tinħall fil-livell attwali, jew mhux malajr biżżejjed.","also":["eskalazzjoni","escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Li ssortja malajr il-kwistjonijiet li jaslu skont kemm huma urġenti u importanti, biex l-agħar tiġi mmaniġġjata l-ewwel.","also":["triaged","għażla skont l-urġenza"]},{"id":"impact","g":"run","word":"Impatt","text":"Kemm xi ħaġa taffettwa lin-nies: kemm-il wieħed, u kemm ħażin.","noTip":1},{"id":"urgency","g":"run","word":"Urġenza","text":"Kemm malajr xi ħaġa trid tiġi mmaniġġjata. L-impatt u l-urġenza flimkien jistabbilixxu l-prijorità.","noTip":1},{"id":"plevels","g":"run","word":"Livelli ta' prijorità (P1, P2…)","text":"Tikketti għal kemm kwistjoni hi urġenti. P1 hi l-aktar serja u teħtieġ azzjoni minnufih.","also":["P1","P2","P3","P4","livelli ta' prijorità","priority levels"]},{"id":"queue","g":"run","word":"Kju tat-tickets","text":"Il-lista ta' talbiet u inċidenti li qed jistennew li jittieħdu.","also":["kjuwijiet tat-tickets","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"L-ewwel linja u t-tieni linja","text":"Livelli ta' appoġġ: l-ewwel linja tirċievi s-sejħa u tirranġa affarijiet sempliċi; it-tieni linja għandha ħiliet aktar fil-fond għal dawk diffiċli. Imsejħa wkoll tier 1 u tier 2.","also":["l-ewwel linja","it-tieni linja","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"L-unika persuna li tmexxi t-tweġiba għal inċident, biex kulħadd ikun jaf min jiddeċiedi u min jagħmel xiex.","also":["incident commanders","kmandant tal-inċident"]},{"id":"responsetime","g":"run","word":"Ħin tat-tweġiba","text":"Kemm idum qabel ma xi ħadd jieħu talba jew inċident għall-ewwel darba.","also":["ħinijiet tat-tweġiba","response time","response times"]},{"id":"resolution","g":"run","word":"Ħin tar-riżoluzzjoni","text":"Kemm idum biex talba jew inċident jinħallu għal kollox, mir-rapport sat-tiswija.","also":["ħinijiet tar-riżoluzzjoni","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Ħin medju ta' rkupru (MTTR)","text":"Bħala medja, kemm idum biex servizz jerġa' jaħdem wara li jinkiser. MTTR jista' jfisser affarijiet kemmxejn differenti, għalhekk għid x'qed tkejjel.","also":["MTTR","mean time to recover","mean time to restore","ħin medju ta' rkupru"]},{"id":"mtbf","g":"run","word":"Ħin medju bejn il-fallimenti (MTBF)","text":"Bħala medja, kemm idum servizz jaħdem qabel ma tinkiser xi ħaġa.","also":["MTBF","mean time between failures","ħin medju bejn il-fallimenti"]},{"id":"cmdb","g":"run","word":"Database tal-immaniġġjar tal-konfigurazzjoni (CMDB)","text":"Il-lista tal-oġġetti kollha tal-konfigurazzjoni tiegħek u kif huma konnessi, biex tkun tista' tara x'jiddependi minn xiex.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Assi","text":"Kull ma għandu valur li tippossjedi jew thallas għalih biex iħaddem is-servizz, bħal laptop, liċenzja tas-software jew dominju.","also":["assi","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Ippjanar tal-kapaċità","text":"Li tiżgura li jkun hemm biżżejjed qawwa tal-kompjuter, ħażna u nies għal dak li ġej.","also":["ippjanar tal-kapaċità","capacity planning","capacity plan","pjan tal-kapaċità"]},{"id":"scaling","g":"run","word":"Skalar","text":"Li tlaħħaq ma' aktar utenti billi tagħti lil magna aktar qawwa (scale up) jew iżżid aktar magni (scale out).","also":["skalar","scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Kontinwità tan-negozju","text":"Pjanijiet biex l-affarijiet importanti jibqgħu għaddejjin meta xi ħaġa kbira tmur ħażin, bħal meta titlef uffiċċju, fornitur ewlieni jew il-kompjuters.","also":["kontinwità tan-negozju","business continuity","business continuity plan","pjan tal-kontinwità tan-negozju"]},{"id":"dr","g":"run","word":"Rkupru minn diżastru (DR)","text":"Il-pjan u l-għodda biex servizz jerġa' jinġieb wara xi ħaġa serja, bħal li titlef data centre sħiħ.","also":["rkupru minn diżastru","disaster recovery","DR"]},{"id":"rto","g":"run","word":"Objettiv tal-ħin ta' rkupru (RTO)","text":"L-itwal ħin li servizz jista' jkun waqaf wara diżastru qabel ma jrid jerġa' jaħdem.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Objettiv tal-punt ta' rkupru (RPO)","text":"Kemm data riċenti tifilħ titlef, imkejla fil-ħin. RPO ta' siegħa jfisser backups mill-inqas kull siegħa.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Redundanza","text":"Li jkollok sostituti lesti, bħal server ieħor, biex falliment wieħed ma jwaqqafx is-servizz.","also":["redundanza","redundancy","ridondanza"]},{"id":"failover","g":"run","word":"Failover","text":"Il-qlib awtomatiku għal sistema spare meta dik tas-soltu tfalli.","also":["fail over","bidla awtomatika għal backup"]},{"id":"spof","g":"run","word":"Punt uniku ta' falliment","text":"Parti waħda li ġġorr kollox magħha meta tinkiser, għax ma hemm l-ebda spare.","also":["punt uniku ta' falliment","single points of failure","single point of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Tieqa tal-manutenzjoni","text":"Ħin ippjanat meta servizz jista' jitwaqqaf jew jimxi bil-mod għall-manutenzjoni, imħabbar lill-utenti minn qabel.","also":["tieqa tal-manutenzjoni","maintenance window","maintenance windows","planned maintenance","manutenzjoni ppjanata"]},{"id":"handover","g":"run","word":"Handover","text":"Li tgħaddi x-xogħol, l-għarfien u r-responsabbiltà lil persuna jew tim ieħor, biex xejn ma jaqa'.","also":["handovers","trasferiment tax-xogħol"]},{"id":"kb","g":"run","word":"Bażi tal-għarfien","text":"Ġabra ta' artikli ta' għajnuna u tweġibiet, għall-utenti u għat-tim.","also":["bażi tal-għarfien","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Sodisfazzjon tal-klijent (CSAT)","text":"Punteġġ mingħand l-utenti li jgħid kemm kienu kuntenti, spiss mistoqsi wara li talba tingħalaq.","also":["CSAT","customer satisfaction","sodisfazzjon tal-klijent"]},{"id":"supplier","g":"run","word":"Fornitur","text":"Kumpanija ta' barra li tiddependi minnha, bħall-fornitur tal-hosting tiegħek. Imsejjaħ ukoll vendor jew parti terza.","also":["fornituri","supplier","suppliers","vendor","vendors","third party","parti terza"],"noTip":1},{"id":"retire","g":"run","word":"Irtirar tas-servizz","text":"Li titfi servizz għal dejjem, b'mod sigur: tgħarraf lill-utenti tiegħu, timmaniġġja d-data u l-aċċess tiegħu, u twaqqaf l-ispejjeż.","also":["irtirar tas-servizz","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Tmiem il-ħajja (EOL)","text":"Meta prodott jieqaf jirċievi aġġornamenti jew appoġġ mingħand min għamlu, għalhekk għandu jinbidel.","also":["EOL","end of life","end-of-life","tmiem il-ħajja"]},{"id":"cybersec","g":"sec","word":"Ċibersigurtà","text":"Li tipproteġi sistemi u data milli xi ħadd jidħol fihom bla permess, jisraqhom jew jagħmlilhom il-ħsara.","also":["ċibersigurtà","cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Awtentikazzjoni","text":"Li tiċċekkja min hu xi ħadd, normalment b'password jew kodiċi. Spiss imqassra għal authn.","also":["awtentikazzjoni","authentication","authn"]},{"id":"authz","g":"sec","word":"Awtorizzazzjoni","text":"Li tiċċekkja x'hu permess jagħmel xi ħadd wara li tkun taf min hu. Spiss imqassra għal authz.","also":["awtorizzazzjoni","authz","authorization","authorisation"]},{"id":"mfa","g":"sec","word":"Awtentikazzjoni b'ħafna fatturi (MFA)","text":"Li tidħol b'żewġ provi jew aktar, bħal password flimkien ma' kodiċi fuq it-telefon tiegħek. Imsejħa wkoll żewġ fatturi (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","awtentikazzjoni b'żewġ fatturi"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Li tidħol darba waħda u jkollok aċċess għal ħafna sistemi, bħal meta tuża l-kont tax-xogħol tiegħek kullimkien.","also":["SSO","dħul uniku"]},{"id":"pwmgr","g":"sec","word":"Maniġer tal-passwords","text":"App li toħloq passwords b'saħħithom u tiftakarhom għalik.","also":["maniġers tal-passwords","password manager","password managers"]},{"id":"secret","g":"sec","word":"Sigriet","text":"Password, ċavetta jew kodiċi privat ieħor li programm juża biex jidħol f'xi ħaġa. Qatt m'għandu jinqasam jew jinkiteb fil-kodiċi.","also":["sigrieti","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"Kodiċi sigriet li jħalli programm juża l-API ta' servizz ieħor, u juri min qed jużaha (u jħallas għaliha).","also":["API keys","ċavetta tal-API"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"Pass temporanju li juri li programm għandu permess jidħol, biex ma jkollux bżonn il-password tiegħek kull darba. Mhuwiex l-istess bħal token tal-AI.","also":["access tokens","token tal-aċċess"]},{"id":"encryption","g":"sec","word":"Kriptaġġ","text":"Li tħawwad l-informazzjoni biex ikun jista' jaqraha biss min għandu ċ-ċavetta t-tajba.","also":["kriptaġġ","encryption","encrypted","encrypt","ikkriptat"]},{"id":"https","g":"sec","word":"HTTPS","text":"Il-mod sigur kif jivvjaġġaw il-paġni tal-web, muri bil-katnazz fil-browser tiegħek, biex ħadd bejniethom ma jista' jaqrahom jew ibiddilhom."},{"id":"cert","g":"sec","word":"Ċertifikat SSL/TLS","text":"Karta tal-ID diġitali li tħalli websajt tipprova min hi u tuża HTTPS. Tiskadi, għalhekk trid tiġġedded.","also":["ċertifikat TLS","ċertifikat SSL","ċertifikat","ċertifikati","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permessi","text":"Ir-regoli dwar min jista' jara jew ibiddel xiex.","also":["permessi","permissions","permission","permess"],"noTip":1},{"id":"leastpriv","g":"sec","word":"L-inqas privileġġ","text":"Li tagħti lil kull persuna jew programm biss l-aċċess li verament jeħtieġu, u biss għal kemm idum ikollhom bżonnu.","also":["l-inqas privileġġ","least privilege","principle of least privilege","prinċipju tal-inqas privileġġ"]},{"id":"rbac","g":"sec","word":"Kontroll tal-aċċess ibbażat fuq ir-rwoli (RBAC)","text":"Li tagħti l-aċċess skont ir-rwol, bħal min jara jew min jedita, minflok persuna persuna.","also":["RBAC","role-based access","role-based access control","aċċess ibbażat fuq ir-rwoli"]},{"id":"vuln","g":"sec","word":"Vulnerabbiltà","text":"Dgħufija li xi ħadd jista' juża biex jidħol jew jagħmel il-ħsara.","also":["vulnerabbiltajiet","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Dgħufija li l-attakkanti jafu biha qabel ma dawk li għamlu s-software ikollhom ċans jirranġawha.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Software ta' ħsara, bħal viruses, magħmul biex iħassar, jispjuna jew jisraq."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware li jagħlaq il-fajls tiegħek u jitlob flus biex jerġa' jiftaħhom. Backups tajbin huma l-aħjar difiża.","also":["ransomware attack","attakk ta' ransomware"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Messaġġi foloz li jippruvaw iqarrqu bik biex tagħti passwords jew flus, jew tiftaħ xi ħaġa ta' ħsara.","also":["phishing email","phishing emails","email ta' phishing"]},{"id":"socialeng","g":"sec","word":"Inġinerija soċjali","text":"Li tqarraq bin-nies, mhux bil-kompjuters, biex jagħtu aċċess, bħal sejħa falza minn “appoġġ tal-IT”."},{"id":"firewall","g":"sec","word":"Firewall","text":"Gwardjan li jiddeċiedi liema traffiku tan-netwerk jista' jidħol jew joħroġ.","also":["firewalls","ħajt tan-nar"]},{"id":"vpn","g":"sec","word":"VPN","text":"Fil-qosor għal virtual private network: rabta privata u mħawwda mal-internet, spiss użata biex jintlaħqu sistemi tax-xogħol b'mod sigur.","also":["virtual private network","netwerk privat virtwali"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Li tgħarraq servizz b'tant traffiku falz li n-nies reali ma jistgħux jużawh. DDoS ifisser li jiġi minn ħafna kompjuters f'daqqa.","also":["DoS","DDoS","denial of service","DDoS attack","attakk DDoS"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Li tikri esperti ħbieb biex jippruvaw jidħlu, biex id-dgħufijiet jinstabu qabel ma jsibuhom attakkanti reali.","also":["pen test","pen testing","penetration testing","pentest","test ta' penetrazzjoni"]},{"id":"audit","g":"sec","word":"Awditu tas-sigurtà","text":"Kontroll bir-reqqa ta' kemm xi ħaġa hi protetta tajjeb, skont lista ta' prattiki tajbin.","also":["awditi tas-sigurtà","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Mudellar tat-theddid","text":"Li taħseb min jista' jattakka xi ħaġa, kif, u x'tagħmel biex twaqqafhom.","also":["mudellar tat-theddid","threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Ksur tad-data","text":"Meta informazzjoni privata toħroġ għand nies li m'għandhomx ikollha, jew tintilef jew tinbidel mingħajr permess.","also":["ksur tad-data","data breach","data breaches"]},{"id":"pii","g":"sec","word":"Data personali","text":"Kull informazzjoni dwar persuna li tista' tiġi identifikata, bħal isem, indirizz tal-email jew post. Imsejħa wkoll PII.","also":["data personali","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Il-liġi Ewropea dwar id-data personali (ir-Renju Unit għandu l-verżjoni tiegħu): iġbor biss dak li teħtieġ, żommu sigur, u ħalli lin-nies jaraw jew iħassru d-data tagħhom.","also":["General Data Protection Regulation","Regolament Ġenerali dwar il-Protezzjoni tad-Data"]},{"id":"dataprot","g":"sec","word":"Protezzjoni tad-data","text":"Li tieħu ħsieb tajjeb id-data personali u skont il-liġi.","also":["protezzjoni tad-data","data protection","data protection law","liġi dwar il-protezzjoni tad-data"]},{"id":"privacypolicy","g":"sec","word":"Politika tal-privatezza","text":"Paġna pubblika li tgħid liema data personali tiġbor, għaliex, u x'tagħmel biha.","also":["politika tal-privatezza","privacy policy","privacy statement","privacy notice","avviż tal-privatezza"]},{"id":"consent","g":"sec","word":"Kunsens","text":"“Iva” ċar u ħieles minn persuna biex id-data tagħha tintuża b'mod partikolari. Tista' tirtirah fi kwalunkwe ħin.","also":["kunsens","consent","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Fajl żgħir li websajt iżżomm fil-browser tiegħek biex tiftakar affarijiet, bħal li tkun dħalt. Xi wħud jeħtieġu l-kunsens tiegħek l-ewwel.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimizzazzjoni tad-data","text":"Li tiġbor u żżomm biss id-data personali li verament teħtieġ għax-xogħol.","also":["minimizzazzjoni tad-data","data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Żamma tad-data","text":"Kemm tinżamm id-data qabel titħassar. Li ma żżommhiex aktar milli jkun meħtieġ hu aktar sigur u spiss ikun rekwiżit tal-liġi.","also":["żamma tad-data","data retention","retention period","perjodu ta' żamma"]},{"id":"anon","g":"sec","word":"Anonimizzazzjoni","text":"Li tibdel id-data biex ħadd ma jkun jista' raġonevolment jiġi identifikat minnha aktar.","also":["anonimizzazzjoni","anonymisation","anonymised","anonymization","anonymous data","data anonima"]},{"id":"pseudo","g":"sec","word":"Psewdonimizzazzjoni","text":"Li tibdel l-ismijiet u dettalji oħra b'kodiċijiet, b'ċavetta miżmuma separata biex terġa' torbothom. Xorta hi data personali.","also":["psewdonimizzazzjoni","pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Ftehim dwar l-ipproċessar tad-data (DPA)","text":"Kuntratt li jgħid kif fornitur jista' jittratta data personali f'ismek.","also":["DPA","data processing agreement","ftehim dwar l-ipproċessar tad-data"]},{"id":"dpia","g":"sec","word":"Valutazzjoni tal-impatt dwar il-protezzjoni tad-data (DPIA)","text":"Ħarsa bir-reqqa, qabel tibda, lejn kif pjan biex tuża data personali jista' jaffettwa lin-nies u kif jitnaqqsu r-riskji.","also":["DPIA","data protection impact assessment","valutazzjoni tal-impatt dwar il-protezzjoni tad-data"]},{"id":"auditlog","g":"sec","word":"Log tal-awditu","text":"Rekord ta' min għamel xiex u meta, biex l-azzjonijiet ikunu jistgħu jiġu vverifikati aktar tard.","also":["log tal-awditu","audit log","audit logs","audit trail","traċċa tal-awditu"]},{"id":"compliance","g":"sec","word":"Konformità","text":"Li ssegwi l-liġijiet, ir-regoli u l-istandards li japplikaw għalik, u tkun tista' turi li tagħmel hekk.","also":["konformità","compliance","compliant","konformi"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Standard internazzjonali magħruf għall-immaniġġjar tas-sigurtà tal-informazzjoni. Il-kumpaniji jistgħu jiġu ċċertifikati skontu.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Rapport Amerikan, ivverifikat minn awdituri esterni, li juri li kumpanija tieħu ħsieb tajjeb tad-data tal-klijenti.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Aġent","text":"AI li taħdem fuq kompitu waħedha: taqra l-kodiċi, tagħmel bidliet, tħaddem kontrolli u tirrapporta lura. Ix-xogħol tagħha xorta jiġi kkontrollat.","also":["aġenti","agent","agents"]},{"id":"token","g":"ai","word":"Token","text":"Il-biċċiet żgħar tat-test li AI taqra u tikteb, madwar tliet kwarti ta' kelma kull waħda. L-użu tal-AI jingħadd f'tokens, għalhekk inqas tokens iħallu aktar mill-pjan tiegħek.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Kmand żgħir li jaħdem waħdu f'mument stabbilit, per eżempju meta tibda sessjoni tal-AI, biex it-tim jisma' l-kummenti tiegħek.","also":["hooks"]},{"id":"ai","g":"ai","word":"Intelliġenza artifiċjali (AI)","text":"Sistemi tal-kompjuter li jagħmlu affarijiet li normalment naħsbu li jeħtieġu persuna, bħall-kitba, it-tweġib ta' mistoqsijiet jew it-tagħrif ta' stampi.","also":["AI","artificial intelligence","intelliġenza artifiċjali"],"noTip":1},{"id":"ml","g":"ai","word":"Tagħlim tal-magni (ML)","text":"Mod kif tagħmel il-kompjuters jitgħallmu mudelli minn ħafna eżempji, minflok ma tagħtihom regoli eżatti.","also":["ML","machine learning","tagħlim tal-magni"]},{"id":"model","g":"ai","word":"Mudell","text":"Il-“moħħ” imħarreġ ta' sistema tal-AI, mibni billi jitgħallem minn għadd kbir ta' eżempji. Il-mudelli jvarjaw fil-ħila, fil-veloċità u fil-prezz.","also":["mudelli","models","AI model","mudell tal-AI"],"noTip":1},{"id":"llm","g":"ai","word":"Mudell lingwistiku kbir (LLM)","text":"Mudell tal-AI imħarreġ fuq ammonti kbar ta' test, biex ikun jista' jaqra u jikteb il-lingwa.","also":["LLM","LLMs","large language model","mudell lingwistiku kbir"]},{"id":"genai","g":"ai","word":"AI ġenerattiva","text":"AI li toħloq affarijiet ġodda, bħal test, stampi jew kodiċi, minflok ma tissortja jew tagħraf biss.","also":["AI ġenerattiva","generative AI","GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Programm li titkellem miegħu bil-lingwa ta' kuljum, bil-kitba jew bil-kliem.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Dak li tagħti lil AI: il-mistoqsija jew l-istruzzjonijiet tiegħek, flimkien ma' kull ma tgħaddilha. Prompts aktar ċari normalment jiksbu tweġibiet aħjar.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"Il-ħila li tikteb prompts li jagħtu riżultati affidabbli u utli."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Struzzjonijiet ta' sfond li AI tirċievi qabel ma tibda l-konversazzjoni, li jistabbilixxu r-rwol u r-regoli tagħha. Huma jiżnu aktar minn dak li tikteb int.","also":["system prompts","system instruction","system instructions","struzzjonijiet tas-sistema"]},{"id":"context","g":"ai","word":"Kuntest","text":"Kull ma l-AI tista' tara waqt li taħdem: l-istruzzjonijiet, il-messaġġi tiegħek, fajls li qrat u tweġibiet preċedenti.","noTip":1},{"id":"ctxwin","g":"ai","word":"Tieqa tal-kuntest","text":"Kemm tista' żżomm f'moħħha l-AI f'daqqa, imkejla f'tokens. Wara dan, il-partijiet eqdem jitwarrbu jew jiġu mqassra.","also":["tieqa tal-kuntest","context window","context windows"]},{"id":"session","g":"ai","word":"Sessjoni","text":"Konversazzjoni waħda ta' xogħol ma' AI, mill-bidu sal-aħħar. Sessjoni ġdida tibda b'memorja friska.","also":["sessjonijiet","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memorja","text":"Noti li AI iżżomm bejn is-sessjonijiet, biex tiftakar il-preferenzi u d-deċiżjonijiet preċedenti tiegħek.","noTip":1},{"id":"hallucination","g":"ai","word":"Alluċinazzjoni","text":"Meta AI tgħid xi ħaġa li tinstema' sigura iżda hi maħluqa jew żbaljata. Iċċekkja l-fatti importanti.","also":["alluċinazzjonijiet","hallucination","hallucinations","hallucinate","hallucinates","jalluċina","talluċina"]},{"id":"training","g":"ai","word":"Taħriġ","text":"Li tgħallem mudell billi turih għadd kbir ta' eżempji, qabel ma jużah xi ħadd.","also":["taħriġ","training","trained","imħarreġ"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Data tat-taħriġ","text":"L-eżempji li minnhom tgħallem mudell. L-għarfien tiegħu jieqaf fid-data li fiha nġabru dawk l-eżempji.","also":["data tat-taħriġ","training data","training set"]},{"id":"cutoff","g":"ai","word":"Limitu tal-għarfien","text":"Id-data meta jintemm l-għarfien mibni ta' AI. Ma tkunx taf b'affarijiet ta' wara sakemm ma tfittixhomx.","also":["limitu tal-għarfien","knowledge cutoff","training cutoff","data tat-tmiem tal-għarfien"]},{"id":"finetune","g":"ai","word":"Irfinar (fine-tuning)","text":"Taħriġ żejjed ta' mudell eżistenti fuq l-eżempji tiegħek stess, biex isir aħjar f'xogħol partikolari.","also":["irfinar","fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inferenza","text":"Mudell tal-AI li verament qed jintuża biex iwieġeb xi ħaġa, għall-kuntrarju ta' meta jkun qed jitħarreġ.","also":["inferenza","inference","model inference"]},{"id":"tooluse","g":"ai","word":"Użu tal-għodda","text":"AI li tkun tista' tagħmel affarijiet, mhux titkellem biss: tħaddem kmandi, taqra fajls jew tfittex fuq il-web, permezz ta' għodda li l-app tagħtiha.","also":["użu tal-għodda","tool use","tool calling","tool call","tool calls","sejħa ta' għodda"]},{"id":"subagent","g":"ai","word":"Sub-aġent","text":"AI li tgħin, li AI prinċipali tgħaddilha xogħol iżgħar u minnha terġa' tieħu r-riżultat.","also":["sub-aġent","subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-aġent","text":"Diversi AIs jaħdmu flimkien fuq biċċa xogħol waħda, kull waħda bil-parti tagħha, bħal tim żgħir.","also":["multi-aġent","multi-agent","multi-agent system","sistema b'ħafna aġenti"]},{"id":"autonomy","g":"ai","word":"Awtonomija","text":"Kemm tista' tagħmel AI waħedha qabel ma jkollha tistaqsi lil xi ħadd.","also":["awtonomija","autonomy","autonomous","awtonomu"]},{"id":"hitl","g":"ai","word":"Bniedem fil-loop","text":"Li żżomm persuna involuta biex tiċċekkja jew tapprova dak li tagħmel l-AI f'mumenti ewlenin. Fl-AI-gile dik int.","also":["bniedem fil-loop","human in the loop","human-in-the-loop","HITL","bniedem fiċ-ċiklu"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limiti u kontrolli li jżommu l-azzjonijiet tal-AI siguri, bħal li tkun meħtieġa approvazzjoni qabel ma xi ħaġa tmur live. Inaqqsu r-riskju ta' żbalji, imma ma jeliminawhomx għal kollox.","also":["guardrail","ħitan tas-sigurtà"]},{"id":"rag","g":"ai","word":"Ġenerazzjoni msaħħa bl-irkupru (RAG)","text":"Li tħalli AI tfittex f'dokumenti tiegħek stess qabel ma twieġeb, biex it-tweġibiet tagħha jkunu bbażati fuq il-fatti tiegħek.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Li tibdel test f'lista ta' numri li taqbad it-tifsira tiegħu, biex kompjuter ikun jista' jsib affarijiet li jfissru affarijiet simili.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Database tal-vettori","text":"Database mibnija biex tfittex f'dawk il-listi ta' numri (embeddings), biex issib materjal b'tifsira simili.","also":["database tal-vettori","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Mod komuni biex tqabbad għodda u sorsi tad-data ma' apps tal-AI, biex AI tkun tista' tużahom.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatura","text":"Issettjar ta' kemm huma avventurużi t-tweġibiet ta' AI. Baxxa tagħti tweġibiet aktar stabbli u prevedibbli; għolja tagħti aktar varjati. L-ebda waħda ma tagħmilha dejjem korretta.","also":["temperatura","temperature","model temperature","temperatura tal-mudell"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodali","text":"Kapaċi taħdem b'aktar minn tip wieħed ta' informazzjoni, bħal test, stampi u ħoss.","also":["multimodali","multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Evalwazzjoni (eval)","text":"Test ippjanat ta' kemm AI tagħmel tajjeb fuq eżempji magħżula, biex tkun tista' tqabbel mudelli jew prompts.","also":["eval","evals","evalwazzjonijiet"]},{"id":"bias","g":"ai","word":"Preġudizzju","text":"Meta AI (jew persuna) tmil b'mod inġust lejn naħa waħda, spiss minħabba dak li tgħallmet minnu.","also":["preġudizzju","bias","biased","preġudikat"],"noTip":1},{"id":"responsible","g":"ai","word":"AI responsabbli","text":"Li tuża l-AI b'mod ġust, sigur u onest, bin-nies xorta responsabbli għar-riżultati.","also":["AI responsabbli","responsible AI","ethical AI","AI etika"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Qerq fejn struzzjonijiet moħbija f'paġna tal-web jew fajl jippruvaw iġiegħlu lil AI tagħmel xi ħaġa li l-utent tagħha ma talabx.","also":["prompt injections","injezzjoni tal-prompt"]},{"id":"ratelimit","g":"ai","word":"Limitu tar-rata","text":"Limitu fuq kemm talbiet tista' tibgħat lil servizz f'ħin stabbilit. Jekk taqbżu, ikollok tistenna.","also":["limitu tar-rata","rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Limitu tal-użu","text":"Kemm xogħol tal-AI jippermetti l-pjan tiegħek f'perjodu, u wara jitwaqqaf jew jiswa aktar.","also":["limitu tal-użu","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Li tibni software l-aktar billi tiddeskrivi lil AI dak li trid u thalliha tikteb il-kodiċi.","also":["vibe-coding","kodifikazzjoni bil-vibe"]},{"id":"budget","g":"money","word":"Baġit","text":"L-ammont ta' flus imwarrab għal xi ħaġa.","also":["baġits","budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Stima tal-ispiża","text":"L-aqwa tbassir ta' kemm se tiswa xi ħaġa qabel ma tibda.","also":["stima tal-ispiża","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Redditu fuq l-investiment (ROI)","text":"Dak li tieħu lura meta mqabbel ma' dak li investejt. Jekk hu pożittiv, kien jiswa.","also":["ROI","return on investment","redditu fuq l-investiment"]},{"id":"tco","g":"money","word":"Spiża totali tas-sjieda (TCO)","text":"Kull ma tiswa verament xi ħaġa matul ħajjitha kollha, mhux biss il-prezz tax-xiri: it-tħaddim, l-appoġġ, l-aġġornamenti u finalment l-irtirar tagħha.","also":["TCO","total cost of ownership","spiża totali tas-sjieda"]},{"id":"capex","g":"money","word":"CapEx u OpEx","text":"CapEx huma flus minfuqa minn qabel fuq affarijiet li żżomm; OpEx hi nefqa kontinwa, bħal kontijiet ta' kull xahar.","also":["CapEx","OpEx","capital expenditure","operating expenditure","nefqa kapitali","nefqa operattiva"]},{"id":"subscription","g":"money","word":"Abbonament","text":"Li thallas regolarment, normalment kull xahar jew kull sena, biex tibqa' tuża xi ħaġa.","also":["abbonamenti","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software bħala servizz (SaaS)","text":"Software li tuża online u thallas għalih b'abbonament, filwaqt li min għamlu jħaddmu għalik.","also":["SaaS","software as a service","software bħala servizz"]},{"id":"payg","g":"money","word":"Ħallas skont l-użu","text":"Li thallas biss għal dak li tuża, bħall-cloud computing jew it-tokens tal-AI.","also":["ħallas skont l-użu","pay as you go","pay-as-you-go","usage-based pricing","prezzijiet ibbażati fuq l-użu"]},{"id":"overage","g":"money","word":"Użu żejjed","text":"Użu 'l fuq minn dak li jinkludi l-pjan tiegħek, li jista' jiswa aktar.","also":["użu żejjed","overage","overages","overage charges","ħlasijiet żejda"]},{"id":"billingalert","g":"money","word":"Allert tal-fatturar","text":"Messaġġ meta n-nefqa jew l-użu jilħqu livell li għażilt. Iwissik, imma mhux dejjem iwaqqaf ħlasijiet ulterjuri.","also":["allert tal-fatturar","billing alert","billing alerts","spending alert","allert tan-nefqa"]},{"id":"freetier","g":"money","word":"Livell b'xejn","text":"Livell b'xejn ta' servizz bi ħlas, b'limiti. Utli biex tibda.","also":["livell b'xejn","free tier","free plan","pjan b'xejn"]},{"id":"pricing","g":"money","word":"Pjan tal-prezzijiet","text":"Il-pakketti differenti li servizz ibigħ, kull wieħed bil-prezz u l-limiti tiegħu.","also":["pjan tal-prezzijiet","pricing plan","pricing plans","price plan","pjanijiet tal-prezzijiet"]},{"id":"licence","g":"money","word":"Liċenzja","text":"Ir-regoli dwar kif tista' tuża, tikkopja, tibdel jew taqsam xi ħaġa li għamel xi ħadd ieħor, bħal software, fonts jew stampi.","also":["liċenzji","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software li l-kodiċi tiegħu jista' jaqrah, juża u spiss jibdel kulħadd b'xejn, taħt ir-regoli tal-liċenzja tiegħu.","also":["open-source","open source software","OSS","software open source","sors miftuħ"]},{"id":"osslicence","g":"money","word":"Liċenzja open source","text":"Ir-regoli li jiġu mal-kodiċi open source. Xi wħud iħallu tagħmel kważi kollox (bħal MIT); xi wħud jitolbu li taqsam il-bidliet tiegħek ukoll (bħal GPL).","also":["liċenzji open source","open source licence","open source licences","MIT licence","GPL","liċenzja MIT"]},{"id":"proprietary","g":"money","word":"Proprjetarju","text":"Proprjetà ta' kumpanija, u ma tistax tikkopjah jew tibdlu liberament. L-oppost ta' open source.","also":["proprjetarju","proprietary","proprietary software","software proprjetarju"]},{"id":"copyright","g":"money","word":"Copyright","text":"Id-dritt legali ta' min joħloq li jikkontrolla l-kopji tax-xogħol tiegħu, inkluż kodiċi u kitba.","also":["copyrighted","dritt tal-awtur"],"noTip":1},{"id":"ip","g":"money","word":"Proprjetà intellettwali (IP)","text":"Ideat u ħolqien li l-liġi tqis bħala proprjetà ta' xi ħadd, bħal kodiċi, disinji, ismijiet u logos.","also":["proprjetà intellettwali","intellectual property","IP"]},{"id":"tos","g":"money","word":"Termini tas-servizz","text":"Ir-regoli li taqbel magħhom meta tuża servizz.","also":["termini tas-servizz","terms of service","terms and conditions","terms of use","termini u kundizzjonijiet","termini tal-użu"]},{"id":"contract","g":"money","word":"Kuntratt","text":"Ftehim miktub bejn żewġ naħat li l-liġi tappoġġa.","also":["kuntratti","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Dikjarazzjoni tax-xogħol (SOW)","text":"Dokument li jistabbilixxi eżattament liema xogħol se jsir, sa meta u bi kemm.","also":["SOW","statement of work","dikjarazzjoni tax-xogħol"]},{"id":"fixedprice","g":"money","word":"Prezz fiss","text":"Prezz miftiehem għax-xogħol kollu, ma jimpurtax kemm idum.","also":["prezz fiss","fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Ħin u materjali","text":"Li thallas għas-sigħat li fil-fatt jinħadmu u għall-affarijiet li fil-fatt jintużaw, minflok prezz stabbilit.","also":["ħin u materjali","time and materials","T&M"]},{"id":"invoice","g":"money","word":"Fattura","text":"Kont li jitlob ħlas għal xogħol magħmul jew oġġetti fornuti.","also":["fatturi","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"Meta jkun diffiċli jew għali wisq li titbiegħed minn fornitur, u tibqa' maqbud miegħu.","also":["lock-in","vendor lock-in","dipendenza fuq il-vendor"]},{"id":"procurement","g":"money","word":"Akkwist","text":"Il-proċess ta' għażla u xiri mingħand fornituri.","also":["akkwist","procurement"]},{"id":"servicecredit","g":"money","word":"Kreditu tas-servizz","text":"Flus lura jew skont li tieħu meta fornitur ma jilħaqx l-SLA tiegħu.","also":["krediti tas-servizz","service credit","service credits"]}]}};
